00262 #  define _rpmalloc_stat_inc(counter) atomic_incr32(counter)
00263 #  define _rpmalloc_stat_dec(counter) atomic_decr32(counter)
00264 #  define _rpmalloc_stat_add(counter, value) atomic_add32(counter, (int32_t)(value))
00265 #  define _rpmalloc_stat_add64(counter, value) atomic_add64(counter, (int64_t)(value))
00266 #  define _rpmalloc_stat_add_peak(counter, value, peak) do { int32_t _cur_count = atomic_add32(counter, (int32_t)(value)); if (_cur_count > (peak)) peak = _cur_count; } while (0)
00267 #  define _rpmalloc_stat_sub(counter, value) atomic_add32(counter, -(int32_t)(value))
00268 #  define _rpmalloc_stat_inc_alloc(heap, class_idx) do { \
00269     int32_t alloc_current = atomic_incr32(&heap->size_class_use[class_idx].alloc_current); \
00270     if (alloc_current > heap->size_class_use[class_idx].alloc_peak) \
00271         heap->size_class_use[class_idx].alloc_peak = alloc_current; \
00272     atomic_incr32(&heap->size_class_use[class_idx].alloc_total); \
00273 } while(0)
00274 #  define _rpmalloc_stat_inc_free(heap, class_idx) do { \
00275     atomic_decr32(&heap->size_class_use[class_idx].alloc_current); \
00276     atomic_incr32(&heap->size_class_use[class_idx].free_total); \
00277 } while(0)
00278 #else
00279 #  define _rpmalloc_stat_inc(counter) do {} while(0)
00280 #  define _rpmalloc_stat_dec(counter) do {} while(0)
00281 #  define _rpmalloc_stat_add(counter, value) do {} while(0)
00282 #  define _rpmalloc_stat_add64(counter, value) do {} while(0)
00283 #  define _rpmalloc_stat_add_peak(counter, value, peak) do {} while (0)
00284 #  define _rpmalloc_stat_sub(counter, value) do {} while(0)
00285 #  define _rpmalloc_stat_inc_alloc(heap, class_idx) do {} while(0)
00286 #  define _rpmalloc_stat_inc_free(heap, class_idx) do {} while(0)
00287 #endif
