00430 // A span can either represent a single span of memory pages with size declared by span_map_count configuration variable,
00431 // or a set of spans in a continuous region, a super span. Any reference to the term "span" usually refers to both a single
00432 // span or a super span. A super span can further be divided into multiple spans (or this, super spans), where the first
00433 // (super)span is the master and subsequent (super)spans are subspans. The master span keeps track of how many subspans
00434 // that are still alive and mapped in virtual memory, and once all subspans and master have been unmapped the entire
00435 // superspan region is released and unmapped (on Windows for example, the entire superspan range has to be released
00436 // in the same call to release the virtual memory range, but individual subranges can be decommitted individually
00437 // to reduce physical memory use).
00438 struct span_t {
00440     void*       free_list;
00442     uint32_t    block_count;
00444     uint32_t    size_class;
00446     uint32_t    free_list_limit;
00448     uint32_t    used_count;
00450     atomicptr_t free_list_deferred;
00452     uint32_t    list_size;
00454     uint32_t    block_size;
00456     uint32_t    flags;
00458     uint32_t    span_count;
00460     uint32_t    total_spans;
00462     uint32_t    offset_from_master;
00464     atomic32_t  remaining_spans;
00466     uint32_t    align_offset;
00468     heap_t*     heap;
00470     span_t*     next;
00472     span_t*     prev;
00473 };
00474 static_assert(sizeof(span_t) <= SPAN_HEADER_SIZE, "span size mismatch");
