00729 static inline uintptr_t
00730 get_thread_id(void) {
00731 #if defined(_WIN32)
00732     return (uintptr_t)((void*)NtCurrentTeb());
00733 #elif (defined(__GNUC__) || defined(__clang__)) && !defined(__CYGWIN__)
00734     uintptr_t tid;
00735 #  if defined(__i386__)
00736     __asm__("movl %%gs:0, %0" : "=r" (tid) : : );
00737 #  elif defined(__x86_64__)
00738 #    if defined(__MACH__)
00739     __asm__("movq %%gs:0, %0" : "=r" (tid) : : );
00740 #    else
00741     __asm__("movq %%fs:0, %0" : "=r" (tid) : : );
00742 #    endif
00743 #  elif defined(__arm__)
00744     __asm__ volatile ("mrc p15, 0, %0, c13, c0, 3" : "=r" (tid));
00745 #  elif defined(__aarch64__)
00746 #    if defined(__MACH__)
00747     // tpidr_el0 likely unused, always return 0 on iOS
00748     __asm__ volatile ("mrs %0, tpidrro_el0" : "=r" (tid));
00749 #    else
00750     __asm__ volatile ("mrs %0, tpidr_el0" : "=r" (tid));
00751 #    endif
00752 #  else
00753     tid = (uintptr_t)((void*)get_thread_heap_raw());
00754 #  endif
00755     return tid;
00756 #else
00757     return (uintptr_t)((void*)get_thread_heap_raw());
00758 #endif
00759 }
00760 
00762 static void
00763 set_thread_heap(heap_t* heap) {
