00782 static void
00783 _rpmalloc_spin(void) {
00784 #if defined(_MSC_VER)
00785     _mm_pause();
00786 #elif defined(__x86_64__) || defined(__i386__)
00787     __asm__ volatile("pause" ::: "memory");
00788 #elif defined(__aarch64__) || (defined(__arm__) && __ARM_ARCH >= 7)
00789     __asm__ volatile("yield" ::: "memory");
00790 #elif defined(__powerpc__) || defined(__powerpc64__)
00791         // No idea if ever been compiled in such archs but ... as precaution
00792     __asm__ volatile("or 27,27,27");
00793 #elif defined(__sparc__)
00794     __asm__ volatile("rd %ccr, %g0 \n\trd %ccr, %g0 \n\trd %ccr, %g0");
00795 #else
00796     struct timespec ts = {0};
00797     nanosleep(&ts, 0);
00798 #endif
00799 }
