00806     // has not been called and shutdown is forced (through _exit) or unclean
00807     if (get_thread_id() == _rpmalloc_main_thread_id)
00808         return;
00809 #endif
00810     if (value)
00811         rpmalloc_thread_finalize(1);
00812 }
