00822 static void
00823 _rpmalloc_set_name(void* address, size_t size) {
00824 #if defined(__linux__) || defined(__ANDROID__)
00825     const char *name = _memory_huge_pages ? _memory_config.huge_page_name : _memory_config.page_name;
00826     if (address == MAP_FAILED || !name)
00827         return;
00828     // If the kernel does not support CONFIG_ANON_VMA_NAME or if the call fails
00829     // (e.g. invalid name) it is a no-op basically.
00830     (void)prctl(PR_SET_VMA, PR_SET_VMA_ANON_NAME, (uintptr_t)address, size, (uintptr_t)name);
00831 #else
00832     (void)sizeof(size);
00833     (void)sizeof(address);
00834 #endif
