00837 
00839 //  size is number of bytes to map
00840 //  offset receives the offset in bytes from start of mapped region
00841 //  returns address to start of mapped region to use
00842 static void*
00843 _rpmalloc_mmap(size_t size, size_t* offset) {
00844     rpmalloc_assert(!(size % _memory_page_size), "Invalid mmap size");
00845     rpmalloc_assert(size >= _memory_page_size, "Invalid mmap size");
00846     void* address = _memory_config.memory_map(size, offset);
00847     if (EXPECTED(address != 0)) {
00848         _rpmalloc_stat_add_peak(&_mapped_pages, (size >> _memory_page_size_shift), _mapped_pages_peak);
00849         _rpmalloc_stat_add(&_mapped_total, (size >> _memory_page_size_shift));
00850     }
00851     return address;
00852 }
00853 
00855 //  address is the memory address to unmap, as returned from _memory_map
00856 //  size is the number of bytes to unmap, which might be less than full region for a partial unmap
00857 //  offset is the offset in bytes to the actual mapped region, as set by _memory_map
00858 //  release is set to 0 for partial unmap, or size of entire range for a full unmap
00859 static void
00860 _rpmalloc_unmap(void* address, size_t size, size_t offset, size_t release) {
00861     rpmalloc_assert(!release || (release >= size), "Invalid unmap size");
00862     rpmalloc_assert(!release || (release >= _memory_page_size), "Invalid unmap size");
00863     if (release) {
00864         rpmalloc_assert(!(release % _memory_page_size), "Invalid unmap size");
00865         _rpmalloc_stat_sub(&_mapped_pages, (release >> _memory_page_size_shift));
00866         _rpmalloc_stat_add(&_unmapped_total, (release >> _memory_page_size_shift));
00867     }
00868     _memory_config.memory_unmap(address, size, offset, release);
00869 }
00870 
00872 static void*
00873 _rpmalloc_mmap_os(size_t size, size_t* offset) {
00874     //Either size is a heap (a single page) or a (multiple) span - we only need to align spans, and only if larger than map granularity
00875     size_t padding = ((size >= _memory_span_size) && (_memory_span_size > _memory_map_granularity)) ? _memory_span_size : 0;
00876     rpmalloc_assert(size >= _memory_page_size, "Invalid mmap size");
00877 #if PLATFORM_WINDOWS
00878     //Ok to MEM_COMMIT - according to MSDN, "actual physical pages are not allocated unless/until the virtual addresses are actually accessed"
00879     void* ptr = VirtualAlloc(0, size + padding, (_memory_huge_pages ? MEM_LARGE_PAGES : 0) | MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
00880     if (!ptr) {
00881         if (_memory_config.map_fail_callback) {
00882             if (_memory_config.map_fail_callback(size + padding))
00883                 return _rpmalloc_mmap_os(size, offset);
00884         } else {
00885             rpmalloc_assert(ptr, "Failed to map virtual memory block");
00886         }
00887         return 0;
00888     }
00889 #else
00890     int flags = MAP_PRIVATE | MAP_ANONYMOUS | MAP_UNINITIALIZED;
00891 #  if defined(__APPLE__) && !TARGET_OS_IPHONE && !TARGET_OS_SIMULATOR
00892     int fd = (int)VM_MAKE_TAG(240U);
00893     if (_memory_huge_pages)
00894         fd |= VM_FLAGS_SUPERPAGE_SIZE_2MB;
00895     void* ptr = mmap(0, size + padding, PROT_READ | PROT_WRITE, flags, fd, 0);
00896 #  elif defined(MAP_HUGETLB)
00897     void* ptr = mmap(0, size + padding, PROT_READ | PROT_WRITE | PROT_MAX(PROT_READ | PROT_WRITE), (_memory_huge_pages ? MAP_HUGETLB : 0) | flags, -1, 0);
00898 #    if defined(MADV_HUGEPAGE)
00899     // In some configurations, huge pages allocations might fail thus
00900     // we fallback to normal allocations and promote the region as transparent huge page
00901     if ((ptr == MAP_FAILED || !ptr) && _memory_huge_pages) {
00902         ptr = mmap(0, size + padding, PROT_READ | PROT_WRITE, flags, -1, 0);
00903         if (ptr && ptr != MAP_FAILED) {
00904             int prm = madvise(ptr, size + padding, MADV_HUGEPAGE);
00905             (void)prm;
00906             rpmalloc_assert((prm == 0), "Failed to promote the page to THP");
00907         }
00908     }
00909 #    endif
00910     _rpmalloc_set_name(ptr, size + padding);
00911 #  elif defined(MAP_ALIGNED)
00912     const size_t align = (sizeof(size_t) * 8) - (size_t)(__builtin_clzl(size - 1));
00913     void* ptr = mmap(0, size + padding, PROT_READ | PROT_WRITE, (_memory_huge_pages ? MAP_ALIGNED(align) : 0) | flags, -1, 0);
00914 #  elif defined(MAP_ALIGN)
00915     caddr_t base = (_memory_huge_pages ? (caddr_t)(4 << 20) : 0);
00916     void* ptr = mmap(base, size + padding, PROT_READ | PROT_WRITE, (_memory_huge_pages ? MAP_ALIGN : 0) | flags, -1, 0);
00917 #  else
00918     void* ptr = mmap(0, size + padding, PROT_READ | PROT_WRITE, flags, -1, 0);
00919 #  endif
00920     if ((ptr == MAP_FAILED) || !ptr) {
00921         if (_memory_config.map_fail_callback) {
00922             if (_memory_config.map_fail_callback(size + padding))
00923                 return _rpmalloc_mmap_os(size, offset);
00924         } else if (errno != ENOMEM) {
00925             rpmalloc_assert((ptr != MAP_FAILED) && ptr, "Failed to map virtual memory block");
00926         }
00927         return 0;
00928     }
00929 #endif
00930     _rpmalloc_stat_add(&_mapped_pages_os, (int32_t)((size + padding) >> _memory_page_size_shift));
00931     if (padding) {
00932         size_t final_padding = padding - ((uintptr_t)ptr & ~_memory_span_mask);
00933         rpmalloc_assert(final_padding <= _memory_span_size, "Internal failure in padding");
00934         rpmalloc_assert(final_padding <= padding, "Internal failure in padding");
00935         rpmalloc_assert(!(final_padding % 8), "Internal failure in padding");
00936         ptr = pointer_offset(ptr, final_padding);
00937         *offset = final_padding >> 3;
00938     }
00939     rpmalloc_assert((size < _memory_span_size) || !((uintptr_t)ptr & ~_memory_span_mask), "Internal failure in padding");
00940     return ptr;
00941 }
00942 
00944 static void
00945 _rpmalloc_unmap_os(void* address, size_t size, size_t offset, size_t release) {
00946     rpmalloc_assert(release || (offset == 0), "Invalid unmap size");
00947     rpmalloc_assert(!release || (release >= _memory_page_size), "Invalid unmap size");
00948     rpmalloc_assert(size >= _memory_page_size, "Invalid unmap size");
00949     if (release && offset) {
00950         offset <<= 3;
00951         address = pointer_offset(address, -(int32_t)offset);
00952         if ((release >= _memory_span_size) && (_memory_span_size > _memory_map_granularity)) {
00953             //Padding is always one span size
00954             release += _memory_span_size;
00955         }
00956     }
00957 #if !DISABLE_UNMAP
00958 #if PLATFORM_WINDOWS
00959     if (!VirtualFree(address, release ? 0 : size, release ? MEM_RELEASE : MEM_DECOMMIT)) {
00960         rpmalloc_assert(0, "Failed to unmap virtual memory block");
00961     }
00962 #else
00963     if (release) {
00964         if (munmap(address, release)) {
00965             rpmalloc_assert(0, "Failed to unmap virtual memory block");
00966         }
00967     } else {
00968 #if defined(MADV_FREE_REUSABLE)
00969         int ret;
00970         while ((ret = madvise(address, size, MADV_FREE_REUSABLE)) == -1 && (errno == EAGAIN))
00971             errno = 0;
00972         if ((ret == -1) && (errno != 0)) {
00973 #elif defined(MADV_DONTNEED)
00974         if (madvise(address, size, MADV_DONTNEED)) {
00975 #elif defined(MADV_PAGEOUT)
00976         if (madvise(address, size, MADV_PAGEOUT)) {
00977 #elif defined(MADV_FREE)
00978         if (madvise(address, size, MADV_FREE)) {
00979 #else
00980         if (posix_madvise(address, size, POSIX_MADV_DONTNEED)) {
00981 #endif
00982             rpmalloc_assert(0, "Failed to madvise virtual memory block as free");
00983         }
00984     }
00985 #endif
00986 #endif
00987     if (release)
00988         _rpmalloc_stat_sub(&_mapped_pages_os, release >> _memory_page_size_shift);
00989 }
