01040 static void
01041 _rpmalloc_span_double_link_list_remove(span_t** head, span_t* span) {
01042     rpmalloc_assert(*head, "Linked list corrupted");
01043     if (*head == span) {
01044         *head = span->next;
01045     } else {
01046         span_t* next_span = span->next;
01047         span_t* prev_span = span->prev;
01048         prev_span->next = next_span;
01049         if (EXPECTED(next_span != 0))
01050             next_span->prev = prev_span;
01051     }
01052 }
