01083 static span_t*
01084 _rpmalloc_span_map_from_reserve(heap_t* heap, size_t span_count) {
01085     //Update the heap span reserve
01086     span_t* span = heap->span_reserve;
01087     heap->span_reserve = (span_t*)pointer_offset(span, span_count * _memory_span_size);
01088     heap->spans_reserved -= (uint32_t)span_count;
01089 
01090     _rpmalloc_span_mark_as_subspan_unless_master(heap->span_reserve_master, span, span_count);
01091     if (span_count <= LARGE_CLASS_COUNT)
01092         _rpmalloc_stat_inc(&heap->span_use[span_count - 1].spans_from_reserved);
01093 
01094     return span;
01095 }
