01098 static size_t
01099 _rpmalloc_span_align_count(size_t span_count) {
01100     size_t request_count = (span_count > _memory_span_map_count) ? span_count : _memory_span_map_count;
01101     if ((_memory_page_size > _memory_span_size) && ((request_count * _memory_span_size) % _memory_page_size))
01102         request_count += _memory_span_map_count - (request_count % _memory_span_map_count);
01103     return request_count;
01104 }
