01107 static void
01108 _rpmalloc_span_initialize(span_t* span, size_t total_span_count, size_t span_count, size_t align_offset) {
01109     span->total_spans = (uint32_t)total_span_count;
01110     span->span_count = (uint32_t)span_count;
01111     span->align_offset = (uint32_t)align_offset;
01112     span->flags = SPAN_FLAG_MASTER;
01113     atomic_store32(&span->remaining_spans, (int32_t)total_span_count);
01114 }
