01116 static void
01117 _rpmalloc_span_unmap(span_t* span);
01118 
01120 static span_t*
01121 _rpmalloc_span_map_aligned_count(heap_t* heap, size_t span_count) {
01122     //If we already have some, but not enough, reserved spans, release those to heap cache and map a new
01123     //full set of spans. Otherwise we would waste memory if page size > span size (huge pages)
01124     size_t aligned_span_count = _rpmalloc_span_align_count(span_count);
01125     size_t align_offset = 0;
01126     span_t* span = (span_t*)_rpmalloc_mmap(aligned_span_count * _memory_span_size, &align_offset);
01127     if (!span)
01128         return 0;
01129     _rpmalloc_span_initialize(span, aligned_span_count, span_count, align_offset);
01130     _rpmalloc_stat_inc(&_master_spans);
01131     if (span_count <= LARGE_CLASS_COUNT)
01132         _rpmalloc_stat_inc(&heap->span_use[span_count - 1].spans_map_calls);
01133     if (aligned_span_count > span_count) {
01134         span_t* reserved_spans = (span_t*)pointer_offset(span, span_count * _memory_span_size);
01135         size_t reserved_count = aligned_span_count - span_count;
01136         if (heap->spans_reserved) {
01137             _rpmalloc_span_mark_as_subspan_unless_master(heap->span_reserve_master, heap->span_reserve, heap->spans_reserved);
01138             _rpmalloc_heap_cache_insert(heap, heap->span_reserve);
01139         }
01140         if (reserved_count > _memory_heap_reserve_count) {
01141             // If huge pages or eager spam map count, the global reserve spin lock is held by caller, _rpmalloc_span_map
01142             rpmalloc_assert(atomic_load32(&_memory_global_lock) == 1, "Global spin lock not held as expected");
01143             size_t remain_count = reserved_count - _memory_heap_reserve_count;
01144             reserved_count = _memory_heap_reserve_count;
01145             span_t* remain_span = (span_t*)pointer_offset(reserved_spans, reserved_count * _memory_span_size);
01146             if (_memory_global_reserve) {
01147                 _rpmalloc_span_mark_as_subspan_unless_master(_memory_global_reserve_master, _memory_global_reserve, _memory_global_reserve_count);
01148                 _rpmalloc_span_unmap(_memory_global_reserve);
01149             }
01150             _rpmalloc_global_set_reserved_spans(span, remain_span, remain_count);
01151         }
01152         _rpmalloc_heap_set_reserved_spans(heap, span, reserved_spans, reserved_count);
01153     }
01154     return span;
01155 }
01156 
01158 static span_t*
01159 _rpmalloc_span_map(heap_t* heap, size_t span_count) {
01160     if (span_count <= heap->spans_reserved)
01161         return _rpmalloc_span_map_from_reserve(heap, span_count);
01162     span_t* span = 0;
01163     int use_global_reserve = (_memory_page_size > _memory_span_size) || (_memory_span_map_count > _memory_heap_reserve_count);
01164     if (use_global_reserve) {
01165         // If huge pages, make sure only one thread maps more memory to avoid bloat
01166         while (!atomic_cas32_acquire(&_memory_global_lock, 1, 0))
01167             _rpmalloc_spin();
01168         if (_memory_global_reserve_count >= span_count) {
01169             size_t reserve_count = (!heap->spans_reserved ? _memory_heap_reserve_count : span_count);
01170             if (_memory_global_reserve_count < reserve_count)
01171                 reserve_count = _memory_global_reserve_count;
01172             span = _rpmalloc_global_get_reserved_spans(reserve_count);
01173             if (span) {
01174                 if (reserve_count > span_count) {
01175                     span_t* reserved_span = (span_t*)pointer_offset(span, span_count << _memory_span_size_shift);
01176                     _rpmalloc_heap_set_reserved_spans(heap, _memory_global_reserve_master, reserved_span, reserve_count - span_count);
01177                 }
01178                 // Already marked as subspan in _rpmalloc_global_get_reserved_spans
01179                 span->span_count = (uint32_t)span_count;
01180             }
01181         }
01182     }
01183     if (!span)
01184         span = _rpmalloc_span_map_aligned_count(heap, span_count);
01185     if (use_global_reserve)
01186         atomic_store32_release(&_memory_global_lock, 0);
01187     return span;
01188 }
01189 
01191 static void
01192 _rpmalloc_span_unmap(span_t* span) {
01193     rpmalloc_assert((span->flags & SPAN_FLAG_MASTER) || (span->flags & SPAN_FLAG_SUBSPAN), "Span flag corrupted");
01194     rpmalloc_assert(!(span->flags & SPAN_FLAG_MASTER) || !(span->flags & SPAN_FLAG_SUBSPAN), "Span flag corrupted");
01195 
01196     int is_master = !!(span->flags & SPAN_FLAG_MASTER);
01197     span_t* master = is_master ? span : ((span_t*)pointer_offset(span, -(intptr_t)((uintptr_t)span->offset_from_master * _memory_span_size)));
01198     rpmalloc_assert(is_master || (span->flags & SPAN_FLAG_SUBSPAN), "Span flag corrupted");
01199     rpmalloc_assert(master->flags & SPAN_FLAG_MASTER, "Span flag corrupted");
01200 
01201     size_t span_count = span->span_count;
01202     if (!is_master) {
01203         //Directly unmap subspans (unless huge pages, in which case we defer and unmap entire page range with master)
01204         rpmalloc_assert(span->align_offset == 0, "Span align offset corrupted");
01205         if (_memory_span_size >= _memory_page_size)
01206             _rpmalloc_unmap(span, span_count * _memory_span_size, 0, 0);
01207     } else {
01208         //Special double flag to denote an unmapped master
01209         //It must be kept in memory since span header must be used
01210         span->flags |= SPAN_FLAG_MASTER | SPAN_FLAG_SUBSPAN | SPAN_FLAG_UNMAPPED_MASTER;
01211         _rpmalloc_stat_add(&_unmapped_master_spans, 1);
01212     }
01213 
01214     if (atomic_add32(&master->remaining_spans, -(int32_t)span_count) <= 0) {
01215         //Everything unmapped, unmap the master span with release flag to unmap the entire range of the super span
01216         rpmalloc_assert(!!(master->flags & SPAN_FLAG_MASTER) && !!(master->flags & SPAN_FLAG_SUBSPAN), "Span flag corrupted");
01217         size_t unmap_count = master->span_count;
01218         if (_memory_span_size < _memory_page_size)
01219             unmap_count = master->total_spans;
01220         _rpmalloc_stat_sub(&_master_spans, 1);
01221         _rpmalloc_stat_sub(&_unmapped_master_spans, 1);
01222         _rpmalloc_unmap(master, unmap_count * _memory_span_size, master->align_offset, (size_t)master->total_spans * _memory_span_size);
01223     }
01224 }
01225 
01227 static void
01228 _rpmalloc_span_release_to_cache(heap_t* heap, span_t* span) {
01229     rpmalloc_assert(heap == span->heap, "Span heap pointer corrupted");
01230     rpmalloc_assert(span->size_class < SIZE_CLASS_COUNT, "Invalid span size class");
01231     rpmalloc_assert(span->span_count == 1, "Invalid span count");
01232 #if ENABLE_ADAPTIVE_THREAD_CACHE || ENABLE_STATISTICS
01233     atomic_decr32(&heap->span_use[0].current);
01234 #endif
01235     _rpmalloc_stat_dec(&heap->size_class_use[span->size_class].spans_current);
01236     if (!heap->finalize) {
01237         _rpmalloc_stat_inc(&heap->span_use[0].spans_to_cache);
01238         _rpmalloc_stat_inc(&heap->size_class_use[span->size_class].spans_to_cache);
01239         if (heap->size_class[span->size_class].cache)
01240             _rpmalloc_heap_cache_insert(heap, heap->size_class[span->size_class].cache);
01241         heap->size_class[span->size_class].cache = span;
01242     } else {
01243         _rpmalloc_span_unmap(span);
01244     }
01245 }
01246 
01249 static uint32_t
01250 free_list_partial_init(void** list, void** first_block, void* page_start, void* block_start, uint32_t block_count, uint32_t block_size) {
01251     rpmalloc_assert(block_count, "Internal failure");
01252     *first_block = block_start;
01253     if (block_count > 1) {
01254         void* free_block = pointer_offset(block_start, block_size);
01255         void* block_end = pointer_offset(block_start, (size_t)block_size * block_count);
01256         //If block size is less than half a memory page, bound init to next memory page boundary
01257         if (block_size < (_memory_page_size >> 1)) {
01258             void* page_end = pointer_offset(page_start, _memory_page_size);
01259             if (page_end < block_end)
01260                 block_end = page_end;
01261         }
01262         *list = free_block;
01263         block_count = 2;
01264         void* next_block = pointer_offset(free_block, block_size);
01265         while (next_block < block_end) {
01266             *((void**)free_block) = next_block;
01267             free_block = next_block;
01268             ++block_count;
01269             next_block = pointer_offset(next_block, block_size);
01270         }
01271         *((void**)free_block) = 0;
01272     } else {
01273         *list = 0;
01274     }
01275     return block_count;
01276 }
01277 
01279 static void*
01280 _rpmalloc_span_initialize_new(heap_t* heap, heap_size_class_t* heap_size_class, span_t* span, uint32_t class_idx) {
01281     rpmalloc_assert(span->span_count == 1, "Internal failure");
01282     size_class_t* size_class = _memory_size_class + class_idx;
01283     span->size_class = class_idx;
01284     span->heap = heap;
01285     span->flags &= ~SPAN_FLAG_ALIGNED_BLOCKS;
01286     span->block_size = size_class->block_size;
01287     span->block_count = size_class->block_count;
01288     span->free_list = 0;
01289     span->list_size = 0;
01290     atomic_store_ptr_release(&span->free_list_deferred, 0);
01291 
01292     //Setup free list. Only initialize one system page worth of free blocks in list
01293     void* block;
01294     span->free_list_limit = free_list_partial_init(&heap_size_class->free_list, &block, 
01295         span, pointer_offset(span, SPAN_HEADER_SIZE), size_class->block_count, size_class->block_size);
01296     //Link span as partial if there remains blocks to be initialized as free list, or full if fully initialized
01297     if (span->free_list_limit < span->block_count) {
01298         _rpmalloc_span_double_link_list_add(&heap_size_class->partial_span, span);
01299         span->used_count = span->free_list_limit;
01300     } else {
01301 #if RPMALLOC_FIRST_CLASS_HEAPS
01302         _rpmalloc_span_double_link_list_add(&heap->full_span[class_idx], span);
01303 #endif
01304         ++heap->full_span_count;
01305         span->used_count = span->block_count;
01306     }
01307     return block;
01308 }
01309 
01310 static void
01311 _rpmalloc_span_extract_free_list_deferred(span_t* span) {
01312     // We need acquire semantics on the CAS operation since we are interested in the list size
01313     // Refer to _rpmalloc_deallocate_defer_small_or_medium for further comments on this dependency
01314     do {
01315         span->free_list = atomic_exchange_ptr_acquire(&span->free_list_deferred, INVALID_POINTER);
01316     } while (span->free_list == INVALID_POINTER);
01317     span->used_count -= span->list_size;
01318     span->list_size = 0;
01319     atomic_store_ptr_release(&span->free_list_deferred, 0);
01320 }
01321 
01322 static int
01323 _rpmalloc_span_is_fully_utilized(span_t* span) {
01324     rpmalloc_assert(span->free_list_limit <= span->block_count, "Span free list corrupted");
01325     return !span->free_list && (span->free_list_limit >= span->block_count);
01326 }
01327 
01328 static int
01329 _rpmalloc_span_finalize(heap_t* heap, size_t iclass, span_t* span, span_t** list_head) {
01330     void* free_list = heap->size_class[iclass].free_list;
01331     span_t* class_span = (span_t*)((uintptr_t)free_list & _memory_span_mask);
01332     if (span == class_span) {
01333         // Adopt the heap class free list back into the span free list
01334         void* block = span->free_list;
01335         void* last_block = 0;
01336         while (block) {
01337             last_block = block;
01338             block = *((void**)block);
01339         }
01340         uint32_t free_count = 0;
01341         block = free_list;
01342         while (block) {
01343             ++free_count;
01344             block = *((void**)block);
01345         }
01346         if (last_block) {
01347             *((void**)last_block) = free_list;
01348         } else {
01349             span->free_list = free_list;
01350         }
01351         heap->size_class[iclass].free_list = 0;
01352         span->used_count -= free_count;
01353     }
01354     //If this assert triggers you have memory leaks
01355     rpmalloc_assert(span->list_size == span->used_count, "Memory leak detected");
01356     if (span->list_size == span->used_count) {
01357         _rpmalloc_stat_dec(&heap->span_use[0].current);
01358         _rpmalloc_stat_dec(&heap->size_class_use[iclass].spans_current);
01359         // This function only used for spans in double linked lists
01360         if (list_head)
01361             _rpmalloc_span_double_link_list_remove(list_head, span);
01362         _rpmalloc_span_unmap(span);
01363         return 1;
01364     }
01365     return 0;
01366 }
