01378 static void
01379 _rpmalloc_global_cache_finalize(global_cache_t* cache) {
01380     while (!atomic_cas32_acquire(&cache->lock, 1, 0))
01381         _rpmalloc_spin();
01382 
01383     for (size_t ispan = 0; ispan < cache->count; ++ispan)
01384         _rpmalloc_span_unmap(cache->span[ispan]);
01385     cache->count = 0;
01386 
01387     while (cache->overflow) {
01388         span_t* span = cache->overflow;
01389         cache->overflow = span->next;
01390         _rpmalloc_span_unmap(span);
01391     }
01392 
01393     atomic_store32_release(&cache->lock, 0);
01394 }
01395 
01396 static void
01397 _rpmalloc_global_cache_insert_spans(span_t** span, size_t span_count, size_t count) {
01398     const size_t cache_limit = (span_count == 1) ? 
01399         GLOBAL_CACHE_MULTIPLIER * MAX_THREAD_SPAN_CACHE :
01400         GLOBAL_CACHE_MULTIPLIER * (MAX_THREAD_SPAN_LARGE_CACHE - (span_count >> 1));
01401 
01402     global_cache_t* cache = &_memory_span_cache[span_count - 1];
01403 
01404     size_t insert_count = count;
01405     while (!atomic_cas32_acquire(&cache->lock, 1, 0))
01406         _rpmalloc_spin();
01407 
01408 #if ENABLE_STATISTICS
01409     cache->insert_count += count;
01410 #endif
01411     if ((cache->count + insert_count) > cache_limit)
01412         insert_count = cache_limit - cache->count;
01413 
01414     memcpy(cache->span + cache->count, span, sizeof(span_t*) * insert_count);
01415     cache->count += (uint32_t)insert_count;
01416 
01417 #if ENABLE_UNLIMITED_CACHE
01418     while (insert_count < count) {
01419 #else
01420     // Enable unlimited cache if huge pages, or we will leak since it is unlikely that an entire huge page
01421     // will be unmapped, and we're unable to partially decommit a huge page
01422     while ((_memory_page_size > _memory_span_size) && (insert_count < count)) {
01423 #endif      
01424         span_t* current_span = span[insert_count++];
01425         current_span->next = cache->overflow;
01426         cache->overflow = current_span;
01427     }
01428     atomic_store32_release(&cache->lock, 0);
01429 
01430     span_t* keep = 0;
01431     for (size_t ispan = insert_count; ispan < count; ++ispan) {
01432         span_t* current_span = span[ispan];
01433         // Keep master spans that has remaining subspans to avoid dangling them
01434         if ((current_span->flags & SPAN_FLAG_MASTER) &&
01435             (atomic_load32(&current_span->remaining_spans) > (int32_t)current_span->span_count)) {
01436             current_span->next = keep;
01437             keep = current_span;
01438         } else {
01439             _rpmalloc_span_unmap(current_span);
01440         }
01441     }
01442 
01443     if (keep) {
01444         while (!atomic_cas32_acquire(&cache->lock, 1, 0))
01445             _rpmalloc_spin();
01446 
01447         size_t islot = 0;
01448         while (keep) {
01449             for (; islot < cache->count; ++islot) {
01450                 span_t* current_span = cache->span[islot];
01451                 if (!(current_span->flags & SPAN_FLAG_MASTER) || ((current_span->flags & SPAN_FLAG_MASTER) &&
01452                     (atomic_load32(&current_span->remaining_spans) <= (int32_t)current_span->span_count))) {
01453                     _rpmalloc_span_unmap(current_span);
01454                     cache->span[islot] = keep;
01455                     break;
01456                 }
01457             }
01458             if (islot == cache->count)
01459                 break;
01460             keep = keep->next;
01461         }
01462 
01463         if (keep) {
01464             span_t* tail = keep;
01465             while (tail->next)
01466                 tail = tail->next;
01467             tail->next = cache->overflow;
01468             cache->overflow = keep;
01469         }
01470 
01471         atomic_store32_release(&cache->lock, 0);
01472     }
01473 }
01474 
01475 static size_t
01476 _rpmalloc_global_cache_extract_spans(span_t** span, size_t span_count, size_t count) {
01477     global_cache_t* cache = &_memory_span_cache[span_count - 1];
01478 
01479     size_t extract_count = 0;
01480     while (!atomic_cas32_acquire(&cache->lock, 1, 0))
01481         _rpmalloc_spin();
01482 
01483 #if ENABLE_STATISTICS
01484     cache->extract_count += count;
01485 #endif
01486     size_t want = count - extract_count;
01487     if (want > cache->count)
01488         want = cache->count;
01489 
01490     memcpy(span + extract_count, cache->span + (cache->count - want), sizeof(span_t*) * want);
01491     cache->count -= (uint32_t)want;
01492     extract_count += want;
01493 
01494     while ((extract_count < count) && cache->overflow) {
01495         span_t* current_span = cache->overflow;
01496         span[extract_count++] = current_span;
01497         cache->overflow = current_span->next;
01498     }
01499 
01500 #if ENABLE_ASSERTS
01501     for (size_t ispan = 0; ispan < extract_count; ++ispan) {
01502         assert(span[ispan]->span_count == span_count);
01503     }
01504 #endif
01505 
01506     atomic_store32_release(&cache->lock, 0);
01507 
01508     return extract_count;
01509 }
01510 
01511 #endif
