01530 static void
01531 _rpmalloc_heap_cache_adopt_deferred(heap_t* heap, span_t** single_span) {
01532     span_t* span = (span_t*)((void*)atomic_exchange_ptr_acquire(&heap->span_free_deferred, 0));
01533     while (span) {
01534         span_t* next_span = (span_t*)span->free_list;
01535         rpmalloc_assert(span->heap == heap, "Span heap pointer corrupted");
01536         if (EXPECTED(span->size_class < SIZE_CLASS_COUNT)) {
01537             rpmalloc_assert(heap->full_span_count, "Heap span counter corrupted");
01538             --heap->full_span_count;
01539             _rpmalloc_stat_dec(&heap->span_use[0].spans_deferred);
01540 #if RPMALLOC_FIRST_CLASS_HEAPS
01541             _rpmalloc_span_double_link_list_remove(&heap->full_span[span->size_class], span);
01542 #endif
01543             _rpmalloc_stat_dec(&heap->span_use[0].current);
01544             _rpmalloc_stat_dec(&heap->size_class_use[span->size_class].spans_current);
01545             if (single_span && !*single_span)
01546                 *single_span = span;
01547             else
01548                 _rpmalloc_heap_cache_insert(heap, span);
01549         } else {
01550             if (span->size_class == SIZE_CLASS_HUGE) {
01551                 _rpmalloc_deallocate_huge(span);
01552             } else {
01553                 rpmalloc_assert(span->size_class == SIZE_CLASS_LARGE, "Span size class invalid");
01554                 rpmalloc_assert(heap->full_span_count, "Heap span counter corrupted");
01555                 --heap->full_span_count;
01556 #if RPMALLOC_FIRST_CLASS_HEAPS
01557                 _rpmalloc_span_double_link_list_remove(&heap->large_huge_span, span);
01558 #endif
01559                 uint32_t idx = span->span_count - 1;
01560                 _rpmalloc_stat_dec(&heap->span_use[idx].spans_deferred);
01561                 _rpmalloc_stat_dec(&heap->span_use[idx].current);
01562                 if (!idx && single_span && !*single_span)
01563                     *single_span = span;
01564                 else
01565                     _rpmalloc_heap_cache_insert(heap, span);
01566             }
01567         }
01568         span = next_span;
01569     }
01570 }
