01572 static void
01573 _rpmalloc_heap_unmap(heap_t* heap) {
01574     if (!heap->master_heap) {
01575         if ((heap->finalize > 1) && !atomic_load32(&heap->child_count)) {
01576             span_t* span = (span_t*)((uintptr_t)heap & _memory_span_mask);
01577             _rpmalloc_span_unmap(span);
01578         }
01579     } else {
01580         if (atomic_decr32(&heap->master_heap->child_count) == 0) {
01581             _rpmalloc_heap_unmap(heap->master_heap);
01582         }
01583     }
01584 }
01585 
01586 static void
01587 _rpmalloc_heap_global_finalize(heap_t* heap) {
01588     if (heap->finalize++ > 1) {
01589         --heap->finalize;
01590         return;
01591     }
01592 
01593     _rpmalloc_heap_finalize(heap);
01594 
01595 #if ENABLE_THREAD_CACHE
01596     for (size_t iclass = 0; iclass < LARGE_CLASS_COUNT; ++iclass) {
01597         span_cache_t* span_cache;
01598         if (!iclass)
01599             span_cache = &heap->span_cache;
01600         else
01601             span_cache = (span_cache_t*)(heap->span_large_cache + (iclass - 1));
01602         for (size_t ispan = 0; ispan < span_cache->count; ++ispan)
01603             _rpmalloc_span_unmap(span_cache->span[ispan]);
01604         span_cache->count = 0;
01605     }
01606 #endif
01607 
01608     if (heap->full_span_count) {
01609         --heap->finalize;
01610         return;
01611     }
01612 
01613     for (size_t iclass = 0; iclass < SIZE_CLASS_COUNT; ++iclass) {
01614         if (heap->size_class[iclass].free_list || heap->size_class[iclass].partial_span) {
01615             --heap->finalize;
01616             return;
01617         }
01618     }
01619     //Heap is now completely free, unmap and remove from heap list
01620     size_t list_idx = (size_t)heap->id % HEAP_ARRAY_SIZE;
01621     heap_t* list_heap = _memory_heaps[list_idx];
01622     if (list_heap == heap) {
01623         _memory_heaps[list_idx] = heap->next_heap;
01624     } else {
01625         while (list_heap->next_heap != heap)
01626             list_heap = list_heap->next_heap;
01627         list_heap->next_heap = heap->next_heap;
01628     }
01629 
01630     _rpmalloc_heap_unmap(heap);
01631 }
01632 
01634 static void
01635 _rpmalloc_heap_cache_insert(heap_t* heap, span_t* span) {
01636     if (UNEXPECTED(heap->finalize != 0)) {
01637         _rpmalloc_span_unmap(span);
01638         _rpmalloc_heap_global_finalize(heap);
01639         return;
01640     }
01641 #if ENABLE_THREAD_CACHE
01642     size_t span_count = span->span_count;
01643     _rpmalloc_stat_inc(&heap->span_use[span_count - 1].spans_to_cache);
01644     if (span_count == 1) {
01645         span_cache_t* span_cache = &heap->span_cache;
01646         span_cache->span[span_cache->count++] = span;
01647         if (span_cache->count == MAX_THREAD_SPAN_CACHE) {
01648             const size_t remain_count = MAX_THREAD_SPAN_CACHE - THREAD_SPAN_CACHE_TRANSFER;
01649 #if ENABLE_GLOBAL_CACHE
01650             _rpmalloc_stat_add64(&heap->thread_to_global, THREAD_SPAN_CACHE_TRANSFER * _memory_span_size);
01651             _rpmalloc_stat_add(&heap->span_use[span_count - 1].spans_to_global, THREAD_SPAN_CACHE_TRANSFER);
01652             _rpmalloc_global_cache_insert_spans(span_cache->span + remain_count, span_count, THREAD_SPAN_CACHE_TRANSFER);
01653 #else
01654             for (size_t ispan = 0; ispan < THREAD_SPAN_CACHE_TRANSFER; ++ispan)
01655                 _rpmalloc_span_unmap(span_cache->span[remain_count + ispan]);
01656 #endif
01657             span_cache->count = remain_count;
01658         }
01659     } else {
01660         size_t cache_idx = span_count - 2;
01661         span_large_cache_t* span_cache = heap->span_large_cache + cache_idx;
01662         span_cache->span[span_cache->count++] = span;
01663         const size_t cache_limit = (MAX_THREAD_SPAN_LARGE_CACHE - (span_count >> 1));
01664         if (span_cache->count == cache_limit) {
01665             const size_t transfer_limit = 2 + (cache_limit >> 2);
01666             const size_t transfer_count = (THREAD_SPAN_LARGE_CACHE_TRANSFER <= transfer_limit ? THREAD_SPAN_LARGE_CACHE_TRANSFER : transfer_limit);
01667             const size_t remain_count = cache_limit - transfer_count;
01668 #if ENABLE_GLOBAL_CACHE
01669             _rpmalloc_stat_add64(&heap->thread_to_global, transfer_count * span_count * _memory_span_size);
01670             _rpmalloc_stat_add(&heap->span_use[span_count - 1].spans_to_global, transfer_count);
01671             _rpmalloc_global_cache_insert_spans(span_cache->span + remain_count, span_count, transfer_count);
01672 #else
01673             for (size_t ispan = 0; ispan < transfer_count; ++ispan)
01674                 _rpmalloc_span_unmap(span_cache->span[remain_count + ispan]);
01675 #endif
01676             span_cache->count = remain_count;
01677         }
01678     }
01679 #else
01680     (void)sizeof(heap);
01681     _rpmalloc_span_unmap(span);
01682 #endif
01683 }
01684 
01686 static span_t*
01687 _rpmalloc_heap_thread_cache_extract(heap_t* heap, size_t span_count) {
01688     span_t* span = 0;
01689 #if ENABLE_THREAD_CACHE
01690     span_cache_t* span_cache;
01691     if (span_count == 1)
01692         span_cache = &heap->span_cache;
01693     else
01694         span_cache = (span_cache_t*)(heap->span_large_cache + (span_count - 2));
01695     if (span_cache->count) {
01696         _rpmalloc_stat_inc(&heap->span_use[span_count - 1].spans_from_cache);
01697         return span_cache->span[--span_cache->count];
01698     }
01699 #endif
01700     return span;
01701 }
