01703 static span_t*
01704 _rpmalloc_heap_thread_cache_deferred_extract(heap_t* heap, size_t span_count) {
01705     span_t* span = 0;
01706     if (span_count == 1) {
01707         _rpmalloc_heap_cache_adopt_deferred(heap, &span);
01708     } else {
01709         _rpmalloc_heap_cache_adopt_deferred(heap, 0);
01710         span = _rpmalloc_heap_thread_cache_extract(heap, span_count);
01711     }
01712     return span;
