01723 static span_t*
01724 _rpmalloc_heap_global_cache_extract(heap_t* heap, size_t span_count) {
01725 #if ENABLE_GLOBAL_CACHE
01726 #if ENABLE_THREAD_CACHE
01727     span_cache_t* span_cache;
01728     size_t wanted_count;
01729     if (span_count == 1) {
01730         span_cache = &heap->span_cache;
01731         wanted_count = THREAD_SPAN_CACHE_TRANSFER;
01732     } else {
01733         span_cache = (span_cache_t*)(heap->span_large_cache + (span_count - 2));
01734         wanted_count = THREAD_SPAN_LARGE_CACHE_TRANSFER;
01735     }
01736     span_cache->count = _rpmalloc_global_cache_extract_spans(span_cache->span, span_count, wanted_count);
01737     if (span_cache->count) {
01738         _rpmalloc_stat_add64(&heap->global_to_thread, span_count * span_cache->count * _memory_span_size);
01739         _rpmalloc_stat_add(&heap->span_use[span_count - 1].spans_from_global, span_cache->count);
01740         return span_cache->span[--span_cache->count];
01741     }
01742 #else
01743     span_t* span = 0;
01744     size_t count = _rpmalloc_global_cache_extract_spans(&span, span_count, 1);
01745     if (count) {
01746         _rpmalloc_stat_add64(&heap->global_to_thread, span_count * count * _memory_span_size);
01747         _rpmalloc_stat_add(&heap->span_use[span_count - 1].spans_from_global, count);
01748         return span;
01749     }
01750 #endif
01751 #endif
01752     (void)sizeof(heap);
01753     (void)sizeof(span_count);
01754     return 0;
01755 }
