01757 static void
01758 _rpmalloc_inc_span_statistics(heap_t* heap, size_t span_count, uint32_t class_idx) {
01759     (void)sizeof(heap);
01760     (void)sizeof(span_count);
01761     (void)sizeof(class_idx);
01762 #if ENABLE_ADAPTIVE_THREAD_CACHE || ENABLE_STATISTICS
01763     uint32_t idx = (uint32_t)span_count - 1;
01764     uint32_t current_count = (uint32_t)atomic_incr32(&heap->span_use[idx].current);
01765     if (current_count > (uint32_t)atomic_load32(&heap->span_use[idx].high))
01766         atomic_store32(&heap->span_use[idx].high, (int32_t)current_count);
01767     _rpmalloc_stat_add_peak(&heap->size_class_use[class_idx].spans_current, 1, heap->size_class_use[class_idx].spans_peak);
