01770 
01772 static span_t*
01773 _rpmalloc_heap_extract_new_span(heap_t* heap, heap_size_class_t* heap_size_class, size_t span_count, uint32_t class_idx) {
01774     span_t* span;
01775 #if ENABLE_THREAD_CACHE
01776     if (heap_size_class && heap_size_class->cache) {
01777         span = heap_size_class->cache;
01778         heap_size_class->cache = (heap->span_cache.count ? heap->span_cache.span[--heap->span_cache.count] : 0);
01779         _rpmalloc_inc_span_statistics(heap, span_count, class_idx);
01780         return span;
01781     }
01782 #endif
01783     (void)sizeof(class_idx);
01784     // Allow 50% overhead to increase cache hits
01785     size_t base_span_count = span_count;
01786     size_t limit_span_count = (span_count > 2) ? (span_count + (span_count >> 1)) : span_count;
01787     if (limit_span_count > LARGE_CLASS_COUNT)
01788         limit_span_count = LARGE_CLASS_COUNT;
01789     do {
01790         span = _rpmalloc_heap_thread_cache_extract(heap, span_count);
01791         if (EXPECTED(span != 0)) {
01792             _rpmalloc_stat_inc(&heap->size_class_use[class_idx].spans_from_cache);
01793             _rpmalloc_inc_span_statistics(heap, span_count, class_idx);
01794             return span;
01795         }
01796         span = _rpmalloc_heap_thread_cache_deferred_extract(heap, span_count);
01797         if (EXPECTED(span != 0)) {
01798             _rpmalloc_stat_inc(&heap->size_class_use[class_idx].spans_from_cache);
01799             _rpmalloc_inc_span_statistics(heap, span_count, class_idx);
01800             return span;
01801         }
01802         span = _rpmalloc_heap_reserved_extract(heap, span_count);
01803         if (EXPECTED(span != 0)) {
01804             _rpmalloc_stat_inc(&heap->size_class_use[class_idx].spans_from_reserved);
01805             _rpmalloc_inc_span_statistics(heap, span_count, class_idx);
01806             return span;
01807         }
01808         span = _rpmalloc_heap_global_cache_extract(heap, span_count);
01809         if (EXPECTED(span != 0)) {
01810             _rpmalloc_stat_inc(&heap->size_class_use[class_idx].spans_from_cache);
01811             _rpmalloc_inc_span_statistics(heap, span_count, class_idx);
01812             return span;
01813         }
01814         ++span_count;
01815     } while (span_count <= limit_span_count);
01816     //Final fallback, map in more virtual memory
01817     span = _rpmalloc_span_map(heap, base_span_count);
01818     _rpmalloc_inc_span_statistics(heap, base_span_count, class_idx);
01819     _rpmalloc_stat_inc(&heap->size_class_use[class_idx].spans_map_calls);
01820     return span;
01821 }
01822 
01823 static void
01824 _rpmalloc_heap_initialize(heap_t* heap) {
01825     memset((void*)heap, 0, sizeof(heap_t));
01826     //Get a new heap ID
01827     heap->id = 1 + atomic_incr32(&_memory_heap_id);
01828 
01829     //Link in heap in heap ID map
01830     size_t list_idx = (size_t)heap->id % HEAP_ARRAY_SIZE;
01831     heap->next_heap = _memory_heaps[list_idx];
01832     _memory_heaps[list_idx] = heap;
01833 }
01834 
01835 static void
01836 _rpmalloc_heap_orphan(heap_t* heap, int first_class) {
01837     heap->owner_thread = (uintptr_t)-1;
01838 #if RPMALLOC_FIRST_CLASS_HEAPS
01839     heap_t** heap_list = (first_class ? &_memory_first_class_orphan_heaps : &_memory_orphan_heaps);
01840 #else
01841     (void)sizeof(first_class);
01842     heap_t** heap_list = &_memory_orphan_heaps;
01843 #endif
01844     heap->next_orphan = *heap_list;
01845     *heap_list = heap;
01846 }
01847 
01849 static heap_t*
01850 _rpmalloc_heap_allocate_new(void) {
01851     // Map in pages for a 16 heaps. If page size is greater than required size for this, map a page and
01852     // use first part for heaps and remaining part for spans for allocations. Adds a lot of complexity,
01853     // but saves a lot of memory on systems where page size > 64 spans (4MiB)
01854     size_t heap_size = sizeof(heap_t);
01855     size_t aligned_heap_size = 16 * ((heap_size + 15) / 16);
01856     size_t request_heap_count = 16;
01857     size_t heap_span_count = ((aligned_heap_size * request_heap_count) + sizeof(span_t) + _memory_span_size - 1) / _memory_span_size;
01858     size_t block_size = _memory_span_size * heap_span_count;
01859     size_t span_count = heap_span_count;
01860     span_t* span = 0;
01861     // If there are global reserved spans, use these first
01862     if (_memory_global_reserve_count >= heap_span_count) {
01863         span = _rpmalloc_global_get_reserved_spans(heap_span_count);
01864     }
01865     if (!span) {
01866         if (_memory_page_size > block_size) {
01867             span_count = _memory_page_size / _memory_span_size;
01868             block_size = _memory_page_size;
01869             // If using huge pages, make sure to grab enough heaps to avoid reallocating a huge page just to serve new heaps
01870             size_t possible_heap_count = (block_size - sizeof(span_t)) / aligned_heap_size;
01871             if (possible_heap_count >= (request_heap_count * 16))
01872                 request_heap_count *= 16;
01873             else if (possible_heap_count < request_heap_count)
01874                 request_heap_count = possible_heap_count;
01875             heap_span_count = ((aligned_heap_size * request_heap_count) + sizeof(span_t) + _memory_span_size - 1) / _memory_span_size;
01876         }
01877 
01878         size_t align_offset = 0;
01879         span = (span_t*)_rpmalloc_mmap(block_size, &align_offset);
01880         if (!span)
01881             return 0;
01882 
01883         // Master span will contain the heaps
01884         _rpmalloc_stat_inc(&_master_spans);
01885         _rpmalloc_span_initialize(span, span_count, heap_span_count, align_offset);
01886     }
01887 
01888     size_t remain_size = _memory_span_size - sizeof(span_t);
01889     heap_t* heap = (heap_t*)pointer_offset(span, sizeof(span_t));
01890     _rpmalloc_heap_initialize(heap);
01891 
01892     // Put extra heaps as orphans
01893     size_t num_heaps = remain_size / aligned_heap_size;
01894     if (num_heaps < request_heap_count)
01895         num_heaps = request_heap_count;
01896     atomic_store32(&heap->child_count, (int32_t)num_heaps - 1);
01897     heap_t* extra_heap = (heap_t*)pointer_offset(heap, aligned_heap_size);
01898     while (num_heaps > 1) {
01899         _rpmalloc_heap_initialize(extra_heap);
01900         extra_heap->master_heap = heap;
01901         _rpmalloc_heap_orphan(extra_heap, 1);
01902         extra_heap = (heap_t*)pointer_offset(extra_heap, aligned_heap_size);
01903         --num_heaps;
01904     }
01905 
01906     if (span_count > heap_span_count) {
01907         // Cap reserved spans
01908         size_t remain_count = span_count - heap_span_count;
01909         size_t reserve_count = (remain_count > _memory_heap_reserve_count ? _memory_heap_reserve_count : remain_count);
01910         span_t* remain_span = (span_t*)pointer_offset(span, heap_span_count * _memory_span_size);
01911         _rpmalloc_heap_set_reserved_spans(heap, span, remain_span, reserve_count);
01912 
01913         if (remain_count > reserve_count) {
01914             // Set to global reserved spans
01915             remain_span = (span_t*)pointer_offset(remain_span, reserve_count * _memory_span_size);
01916             reserve_count = remain_count - reserve_count;
01917             _rpmalloc_global_set_reserved_spans(span, remain_span, reserve_count);
01918         }
01919     }
01920 
01921     return heap;
01922 }
01923 
01924 static heap_t*
01925 _rpmalloc_heap_extract_orphan(heap_t** heap_list) {
01926     heap_t* heap = *heap_list;
01927     *heap_list = (heap ? heap->next_orphan : 0);
01928     return heap;
01929 }
01930 
01932 static heap_t*
01933 _rpmalloc_heap_allocate(int first_class) {
01934     heap_t* heap = 0;
01935     while (!atomic_cas32_acquire(&_memory_global_lock, 1, 0))
01936         _rpmalloc_spin();
01937     if (first_class == 0)
01938         heap = _rpmalloc_heap_extract_orphan(&_memory_orphan_heaps);
01939 #if RPMALLOC_FIRST_CLASS_HEAPS
01940     if (!heap)
01941         heap = _rpmalloc_heap_extract_orphan(&_memory_first_class_orphan_heaps);
01942 #endif
01943     if (!heap)
01944         heap = _rpmalloc_heap_allocate_new();
01945     atomic_store32_release(&_memory_global_lock, 0);
01946     _rpmalloc_heap_cache_adopt_deferred(heap, 0);
01947     return heap;
01948 }
01949 
01950 extern thread_local bool RpThreadShutdown;
01951 
01952 static void
01953 _rpmalloc_heap_release(void* heapptr, int first_class, int release_cache) {
01954     heap_t* heap = (heap_t*)heapptr;
01955     if (!heap)
01956         return;
01957     RpThreadShutdown = true;
01958     //Release thread cache spans back to global cache
01959     _rpmalloc_heap_cache_adopt_deferred(heap, 0);
01960     if (release_cache  || heap->finalize) {
01961 #if ENABLE_THREAD_CACHE
01962         for (size_t iclass = 0; iclass < LARGE_CLASS_COUNT; ++iclass) {
01963             span_cache_t* span_cache;
01964             if (!iclass)
01965                 span_cache = &heap->span_cache;
01966             else
01967                 span_cache = (span_cache_t*)(heap->span_large_cache + (iclass - 1));
01968             if (!span_cache->count)
01969                 continue;
01970 #if ENABLE_GLOBAL_CACHE
01971             if (heap->finalize) {
01972                 for (size_t ispan = 0; ispan < span_cache->count; ++ispan)
01973                     _rpmalloc_span_unmap(span_cache->span[ispan]);
01974             } else {
01975                 _rpmalloc_stat_add64(&heap->thread_to_global, span_cache->count * (iclass + 1) * _memory_span_size);
01976                 _rpmalloc_stat_add(&heap->span_use[iclass].spans_to_global, span_cache->count);
01977                 _rpmalloc_global_cache_insert_spans(span_cache->span, iclass + 1, span_cache->count);
01978             }
01979 #else
01980             for (size_t ispan = 0; ispan < span_cache->count; ++ispan)
01981                 _rpmalloc_span_unmap(span_cache->span[ispan]);
01982 #endif
01983             span_cache->count = 0;
01984         }
01985 #endif
01986     }
01987 
01988     if (get_thread_heap_raw() == heap)
01989         set_thread_heap(0);
01990 
01991 #if ENABLE_STATISTICS
01992     atomic_decr32(&_memory_active_heaps);
01993     rpmalloc_assert(atomic_load32(&_memory_active_heaps) >= 0, "Still active heaps during finalization");
01994 #endif
01995 
01996     // If we are forcibly terminating with _exit the state of the
01997     // lock atomic is unknown and it's best to just go ahead and exit
01998     if (get_thread_id() != _rpmalloc_main_thread_id) {
01999         while (!atomic_cas32_acquire(&_memory_global_lock, 1, 0))
02000             _rpmalloc_spin();
02001     }
02002     _rpmalloc_heap_orphan(heap, first_class);
02003     atomic_store32_release(&_memory_global_lock, 0);
02004 }
02005 
02006 static void
02007 _rpmalloc_heap_release_raw(void* heapptr, int release_cache) {
02008     _rpmalloc_heap_release(heapptr, 0, release_cache);
02009 }
02010 
02011 static void
02012 _rpmalloc_heap_release_raw_fc(void* heapptr) {
02013     _rpmalloc_heap_release_raw(heapptr, 1);
02014 }
02015 
02016 static void
02017 _rpmalloc_heap_finalize(heap_t* heap) {
02018     if (heap->spans_reserved) {
02019         span_t* span = _rpmalloc_span_map(heap, heap->spans_reserved);
02020         _rpmalloc_span_unmap(span);
02021         heap->spans_reserved = 0;
02022     }
02023 
02024     _rpmalloc_heap_cache_adopt_deferred(heap, 0);
02025 
02026     for (size_t iclass = 0; iclass < SIZE_CLASS_COUNT; ++iclass) {
02027         if (heap->size_class[iclass].cache)
02028             _rpmalloc_span_unmap(heap->size_class[iclass].cache);
02029         heap->size_class[iclass].cache = 0;
02030         span_t* span = heap->size_class[iclass].partial_span;
02031         while (span) {
02032             span_t* next = span->next;
02033             _rpmalloc_span_finalize(heap, iclass, span, &heap->size_class[iclass].partial_span);
02034             span = next;
02035         }
02036         // If class still has a free list it must be a full span
02037         if (heap->size_class[iclass].free_list) {
02038             span_t* class_span = (span_t*)((uintptr_t)heap->size_class[iclass].free_list & _memory_span_mask);
02039             span_t** list = 0;
02040 #if RPMALLOC_FIRST_CLASS_HEAPS
02041             list = &heap->full_span[iclass];
02042 #endif
02043             --heap->full_span_count;
02044             if (!_rpmalloc_span_finalize(heap, iclass, class_span, list)) {
02045                 if (list)
02046                     _rpmalloc_span_double_link_list_remove(list, class_span);
02047                 _rpmalloc_span_double_link_list_add(&heap->size_class[iclass].partial_span, class_span);
02048             }
02049         }
02050     }
02051 
02052 #if ENABLE_THREAD_CACHE
02053     for (size_t iclass = 0; iclass < LARGE_CLASS_COUNT; ++iclass) {
02054         span_cache_t* span_cache;
02055         if (!iclass)
02056             span_cache = &heap->span_cache;
02057         else
02058             span_cache = (span_cache_t*)(heap->span_large_cache + (iclass - 1));
02059         for (size_t ispan = 0; ispan < span_cache->count; ++ispan)
02060             _rpmalloc_span_unmap(span_cache->span[ispan]);
02061         span_cache->count = 0;
02062     }
02063 #endif
02064     rpmalloc_assert(!atomic_load_ptr(&heap->span_free_deferred), "Heaps still active during finalization");
02065 }
02066 
02067 
02073 
02075 static void*
02076 free_list_pop(void** list) {
02077     void* block = *list;
02078     *list = *((void**)block);
02079     return block;
02080 }
02081 
02083 static void*
02084 _rpmalloc_allocate_from_heap_fallback(heap_t* heap, heap_size_class_t* heap_size_class, uint32_t class_idx) {
02085     span_t* span = heap_size_class->partial_span;
02086     if (EXPECTED(span != 0)) {
02087         rpmalloc_assert(span->block_count == _memory_size_class[span->size_class].block_count, "Span block count corrupted");
02088         rpmalloc_assert(!_rpmalloc_span_is_fully_utilized(span), "Internal failure");
02089         void* block;
02090         if (span->free_list) {
02091             //Span local free list is not empty, swap to size class free list
02092             block = free_list_pop(&span->free_list);
02093             heap_size_class->free_list = span->free_list;
02094             span->free_list = 0;
02095         } else {
02096             //If the span did not fully initialize free list, link up another page worth of blocks          
02097             void* block_start = pointer_offset(span, SPAN_HEADER_SIZE + ((size_t)span->free_list_limit * span->block_size));
02098             span->free_list_limit += free_list_partial_init(&heap_size_class->free_list, &block,
02099                 (void*)((uintptr_t)block_start & ~(_memory_page_size - 1)), block_start,
02100                 span->block_count - span->free_list_limit, span->block_size);
02101         }
02102         rpmalloc_assert(span->free_list_limit <= span->block_count, "Span block count corrupted");
02103         span->used_count = span->free_list_limit;
02104 
02105         //Swap in deferred free list if present
02106         if (atomic_load_ptr(&span->free_list_deferred))
02107             _rpmalloc_span_extract_free_list_deferred(span);
02108 
02109         //If span is still not fully utilized keep it in partial list and early return block
02110         if (!_rpmalloc_span_is_fully_utilized(span))
02111             return block;
02112 
02113         //The span is fully utilized, unlink from partial list and add to fully utilized list
02114         _rpmalloc_span_double_link_list_pop_head(&heap_size_class->partial_span, span);
02115 #if RPMALLOC_FIRST_CLASS_HEAPS
02116         _rpmalloc_span_double_link_list_add(&heap->full_span[class_idx], span);
02117 #endif
02118         ++heap->full_span_count;
02119         return block;
02120     }
02121 
02122     //Find a span in one of the cache levels
02123     span = _rpmalloc_heap_extract_new_span(heap, heap_size_class, 1, class_idx);
02124     if (EXPECTED(span != 0)) {
02125         //Mark span as owned by this heap and set base data, return first block
02126         return _rpmalloc_span_initialize_new(heap, heap_size_class, span, class_idx);
02127     }
02128 
02129     return 0;
02130 }
02131 
02133 static void*
02134 _rpmalloc_allocate_small(heap_t* heap, size_t size) {
02135     rpmalloc_assert(heap, "No thread heap");
02136     //Small sizes have unique size classes
02137     const uint32_t class_idx = (uint32_t)((size + (SMALL_GRANULARITY - 1)) >> SMALL_GRANULARITY_SHIFT);
02138     heap_size_class_t* heap_size_class = heap->size_class + class_idx;
02139     _rpmalloc_stat_inc_alloc(heap, class_idx);
02140     if (EXPECTED(heap_size_class->free_list != 0))
02141         return free_list_pop(&heap_size_class->free_list);
02142     return _rpmalloc_allocate_from_heap_fallback(heap, heap_size_class, class_idx);
02143 }
02144 
02146 static void*
02147 _rpmalloc_allocate_medium(heap_t* heap, size_t size) {
02148     rpmalloc_assert(heap, "No thread heap");
02149     //Calculate the size class index and do a dependent lookup of the final class index (in case of merged classes)
02150     const uint32_t base_idx = (uint32_t)(SMALL_CLASS_COUNT + ((size - (SMALL_SIZE_LIMIT + 1)) >> MEDIUM_GRANULARITY_SHIFT));
02151     const uint32_t class_idx = _memory_size_class[base_idx].class_idx;
02152     heap_size_class_t* heap_size_class = heap->size_class + class_idx;
02153     _rpmalloc_stat_inc_alloc(heap, class_idx);
02154     if (EXPECTED(heap_size_class->free_list != 0))
02155         return free_list_pop(&heap_size_class->free_list);
02156     return _rpmalloc_allocate_from_heap_fallback(heap, heap_size_class, class_idx);
02157 }
02158 
02160 static void*
02161 _rpmalloc_allocate_large(heap_t* heap, size_t size) {
02162     rpmalloc_assert(heap, "No thread heap");
02163     //Calculate number of needed max sized spans (including header)
02164     //Since this function is never called if size > LARGE_SIZE_LIMIT
02165     //the span_count is guaranteed to be <= LARGE_CLASS_COUNT
02166     size += SPAN_HEADER_SIZE;
02167     size_t span_count = size >> _memory_span_size_shift;
02168     if (size & (_memory_span_size - 1))
02169         ++span_count;
02170 
02171     //Find a span in one of the cache levels
02172     span_t* span = _rpmalloc_heap_extract_new_span(heap, 0, span_count, SIZE_CLASS_LARGE);
02173     if (!span)
02174         return span;
02175 
02176     //Mark span as owned by this heap and set base data
02177     rpmalloc_assert(span->span_count >= span_count, "Internal failure");
02178     span->size_class = SIZE_CLASS_LARGE;
02179     span->heap = heap;
02180 
02181 #if RPMALLOC_FIRST_CLASS_HEAPS
02182     _rpmalloc_span_double_link_list_add(&heap->large_huge_span, span);
02183 #endif
02184     ++heap->full_span_count;
02185 
02186     return pointer_offset(span, SPAN_HEADER_SIZE);
02187 }
02188 
02190 static void*
02191 _rpmalloc_allocate_huge(heap_t* heap, size_t size) {
02192     rpmalloc_assert(heap, "No thread heap");
02193     _rpmalloc_heap_cache_adopt_deferred(heap, 0);
02194     size += SPAN_HEADER_SIZE;
02195     size_t num_pages = size >> _memory_page_size_shift;
02196     if (size & (_memory_page_size - 1))
02197         ++num_pages;
02198     size_t align_offset = 0;
02199     span_t* span = (span_t*)_rpmalloc_mmap(num_pages * _memory_page_size, &align_offset);
02200     if (!span)
02201         return span;
02202 
02203     //Store page count in span_count
02204     span->size_class = SIZE_CLASS_HUGE;
02205     span->span_count = (uint32_t)num_pages;
02206     span->align_offset = (uint32_t)align_offset;
02207     span->heap = heap;
02208     _rpmalloc_stat_add_peak(&_huge_pages_current, num_pages, _huge_pages_peak);
02209 
02210 #if RPMALLOC_FIRST_CLASS_HEAPS
02211     _rpmalloc_span_double_link_list_add(&heap->large_huge_span, span);
02212 #endif
02213     ++heap->full_span_count;
02214 
02215     return pointer_offset(span, SPAN_HEADER_SIZE);
02216 }
02217 
02219 static void*
02220 _rpmalloc_allocate(heap_t* heap, size_t size) {
02221     _rpmalloc_stat_add64(&_allocation_counter, 1);
02222     if (EXPECTED(size <= SMALL_SIZE_LIMIT))
02223         return _rpmalloc_allocate_small(heap, size);
02224     else if (size <= _memory_medium_size_limit)
02225         return _rpmalloc_allocate_medium(heap, size);
02226     else if (size <= LARGE_SIZE_LIMIT)
02227         return _rpmalloc_allocate_large(heap, size);
02228     return _rpmalloc_allocate_huge(heap, size);
02229 }
02230 
02231 static void*
02232 _rpmalloc_aligned_allocate(heap_t* heap, size_t alignment, size_t size) {
02233     if (alignment <= SMALL_GRANULARITY)
02234         return _rpmalloc_allocate(heap, size);
02235 
02236 #if ENABLE_VALIDATE_ARGS
02237     if ((size + alignment) < size) {
02238         errno = EINVAL;
02239         return 0;
02240     }
02241     if (alignment & (alignment - 1)) {
02242         errno = EINVAL;
02243         return 0;
02244     }
02245 #endif
02246 
02247     if ((alignment <= SPAN_HEADER_SIZE) && (size < _memory_medium_size_limit)) {
02248         // If alignment is less or equal to span header size (which is power of two),
02249         // and size aligned to span header size multiples is less than size + alignment,
02250         // then use natural alignment of blocks to provide alignment
02251         size_t multiple_size = size ? (size + (SPAN_HEADER_SIZE - 1)) & ~(uintptr_t)(SPAN_HEADER_SIZE - 1) : SPAN_HEADER_SIZE;
02252         rpmalloc_assert(!(multiple_size % SPAN_HEADER_SIZE), "Failed alignment calculation");
02253         if (multiple_size <= (size + alignment))
02254             return _rpmalloc_allocate(heap, multiple_size);
02255     }
02256 
02257     void* ptr = 0;
02258     size_t align_mask = alignment - 1;
02259     if (alignment <= _memory_page_size) {
02260         ptr = _rpmalloc_allocate(heap, size + alignment);
02261         if ((uintptr_t)ptr & align_mask) {
02262             ptr = (void*)(((uintptr_t)ptr & ~(uintptr_t)align_mask) + alignment);
02263             //Mark as having aligned blocks
02264             span_t* span = (span_t*)((uintptr_t)ptr & _memory_span_mask);
02265             span->flags |= SPAN_FLAG_ALIGNED_BLOCKS;
02266         }
02267         return ptr;
02268     }
02269 
02270     // Fallback to mapping new pages for this request. Since pointers passed
02271     // to rpfree must be able to reach the start of the span by bitmasking of
02272     // the address with the span size, the returned aligned pointer from this
02273     // function must be with a span size of the start of the mapped area.
02274     // In worst case this requires us to loop and map pages until we get a
02275     // suitable memory address. It also means we can never align to span size
02276     // or greater, since the span header will push alignment more than one
02277     // span size away from span start (thus causing pointer mask to give us
02278     // an invalid span start on free)
02279     if (alignment & align_mask) {
02280         errno = EINVAL;
02281         return 0;
02282     }
02283     if (alignment >= _memory_span_size) {
02284         errno = EINVAL;
02285         return 0;
02286     }
02287 
02288     size_t extra_pages = alignment / _memory_page_size;
02289 
02290     // Since each span has a header, we will at least need one extra memory page
02291     size_t num_pages = 1 + (size / _memory_page_size);
02292     if (size & (_memory_page_size - 1))
02293         ++num_pages;
02294 
02295     if (extra_pages > num_pages)
02296         num_pages = 1 + extra_pages;
02297 
02298     size_t original_pages = num_pages;
02299     size_t limit_pages = (_memory_span_size / _memory_page_size) * 2;
02300     if (limit_pages < (original_pages * 2))
02301         limit_pages = original_pages * 2;
02302 
02303     size_t mapped_size, align_offset;
02304     span_t* span;
02305 
02306 retry:
02307     align_offset = 0;
02308     mapped_size = num_pages * _memory_page_size;
02309 
02310     span = (span_t*)_rpmalloc_mmap(mapped_size, &align_offset);
02311     if (!span) {
02312         errno = ENOMEM;
02313         return 0;
02314     }
02315     ptr = pointer_offset(span, SPAN_HEADER_SIZE);
02316 
02317     if ((uintptr_t)ptr & align_mask)
02318         ptr = (void*)(((uintptr_t)ptr & ~(uintptr_t)align_mask) + alignment);
02319 
02320     if (((size_t)pointer_diff(ptr, span) >= _memory_span_size) ||
02321         (pointer_offset(ptr, size) > pointer_offset(span, mapped_size)) ||
02322         (((uintptr_t)ptr & _memory_span_mask) != (uintptr_t)span)) {
02323         _rpmalloc_unmap(span, mapped_size, align_offset, mapped_size);
02324         ++num_pages;
02325         if (num_pages > limit_pages) {
02326             errno = EINVAL;
02327             return 0;
02328         }
02329         goto retry;
02330     }
02331 
02332     //Store page count in span_count
02333     span->size_class = SIZE_CLASS_HUGE;
02334     span->span_count = (uint32_t)num_pages;
02335     span->align_offset = (uint32_t)align_offset;
02336     span->heap = heap;
02337     _rpmalloc_stat_add_peak(&_huge_pages_current, num_pages, _huge_pages_peak);
02338 
02339 #if RPMALLOC_FIRST_CLASS_HEAPS
02340     _rpmalloc_span_double_link_list_add(&heap->large_huge_span, span);
02341 #endif
02342     ++heap->full_span_count;
02343 
02344     _rpmalloc_stat_add64(&_allocation_counter, 1);
02345 
02346     return ptr;
02347 }
02348 
02349 
02355 
02357 static void
02358 _rpmalloc_deallocate_direct_small_or_medium(span_t* span, void* block) {
02359     heap_t* heap = span->heap;
02360     rpmalloc_assert(heap->owner_thread == get_thread_id() || !heap->owner_thread || heap->finalize, "Internal failure");
02361     //Add block to free list
02362     if (UNEXPECTED(_rpmalloc_span_is_fully_utilized(span))) {
02363         span->used_count = span->block_count;
02364 #if RPMALLOC_FIRST_CLASS_HEAPS
02365         _rpmalloc_span_double_link_list_remove(&heap->full_span[span->size_class], span);
02366 #endif
02367         _rpmalloc_span_double_link_list_add(&heap->size_class[span->size_class].partial_span, span);
02368         --heap->full_span_count;
02369     }
02370     *((void**)block) = span->free_list;
02371     --span->used_count;
02372     span->free_list = block;
02373     if (UNEXPECTED(span->used_count == span->list_size)) {
02374         // If there are no used blocks it is guaranteed that no other external thread is accessing the span
02375         if (span->used_count) {
02376             // Make sure we have synchronized the deferred list and list size by using acquire semantics
02377             // and guarantee that no external thread is accessing span concurrently
02378             void* free_list;
02379             do {
02380                 free_list = atomic_exchange_ptr_acquire(&span->free_list_deferred, INVALID_POINTER);
02381             } while (free_list == INVALID_POINTER);
02382             atomic_store_ptr_release(&span->free_list_deferred, free_list);
02383         }
02384         _rpmalloc_span_double_link_list_remove(&heap->size_class[span->size_class].partial_span, span);
02385         _rpmalloc_span_release_to_cache(heap, span);
02386     }
02387 }
02388 
02389 static void
02390 _rpmalloc_deallocate_defer_free_span(heap_t* heap, span_t* span) {
02391     if (span->size_class != SIZE_CLASS_HUGE)
02392         _rpmalloc_stat_inc(&heap->span_use[span->span_count - 1].spans_deferred);
02393     //This list does not need ABA protection, no mutable side state
02394     do {
02395         span->free_list = (void*)atomic_load_ptr(&heap->span_free_deferred);
02396     } while (!atomic_cas_ptr(&heap->span_free_deferred, span, span->free_list));
02397 }
02398 
02400 static void
02401 _rpmalloc_deallocate_defer_small_or_medium(span_t* span, void* block) {
02402     // The memory ordering here is a bit tricky, to avoid having to ABA protect
02403     // the deferred free list to avoid desynchronization of list and list size
02404     // we need to have acquire semantics on successful CAS of the pointer to
02405     // guarantee the list_size variable validity + release semantics on pointer store
02406     void* free_list;
02407     do {
02408         free_list = atomic_exchange_ptr_acquire(&span->free_list_deferred, INVALID_POINTER);
02409     } while (free_list == INVALID_POINTER);
02410     *((void**)block) = free_list;
02411     uint32_t free_count = ++span->list_size;
02412     int all_deferred_free = (free_count == span->block_count);
02413     atomic_store_ptr_release(&span->free_list_deferred, block);
02414     if (all_deferred_free) {
02415         // Span was completely freed by this block. Due to the INVALID_POINTER spin lock
02416         // no other thread can reach this state simultaneously on this span.
02417         // Safe to move to owner heap deferred cache
02418         _rpmalloc_deallocate_defer_free_span(span->heap, span);
02419     }
02420 }
02421 
02422 static void
02423 _rpmalloc_deallocate_small_or_medium(span_t* span, void* p) {
02424     _rpmalloc_stat_inc_free(span->heap, span->size_class);
02425     if (span->flags & SPAN_FLAG_ALIGNED_BLOCKS) {
02426         //Realign pointer to block start
02427         void* blocks_start = pointer_offset(span, SPAN_HEADER_SIZE);
02428         uint32_t block_offset = (uint32_t)pointer_diff(p, blocks_start);
02429         p = pointer_offset(p, -(int32_t)(block_offset % span->block_size));
02430     }
02431     //Check if block belongs to this heap or if deallocation should be deferred
02432 #if RPMALLOC_FIRST_CLASS_HEAPS
02433     int defer = (span->heap->owner_thread && (span->heap->owner_thread != get_thread_id()) && !span->heap->finalize);
02434 #else
02435     int defer = ((span->heap->owner_thread != get_thread_id()) && !span->heap->finalize);
02436 #endif
02437     if (!defer)
02438         _rpmalloc_deallocate_direct_small_or_medium(span, p);
02439     else
02440         _rpmalloc_deallocate_defer_small_or_medium(span, p);
02441 }
02442 
02444 static void
02445 _rpmalloc_deallocate_large(span_t* span) {
02446     rpmalloc_assert(span->size_class == SIZE_CLASS_LARGE, "Bad span size class");
02447     rpmalloc_assert(!(span->flags & SPAN_FLAG_MASTER) || !(span->flags & SPAN_FLAG_SUBSPAN), "Span flag corrupted");
02448     rpmalloc_assert((span->flags & SPAN_FLAG_MASTER) || (span->flags & SPAN_FLAG_SUBSPAN), "Span flag corrupted");
02449     //We must always defer (unless finalizing) if from another heap since we cannot touch the list or counters of another heap
02450 #if RPMALLOC_FIRST_CLASS_HEAPS
02451     int defer = (span->heap->owner_thread && (span->heap->owner_thread != get_thread_id()) && !span->heap->finalize);
02452 #else
02453     int defer = ((span->heap->owner_thread != get_thread_id()) && !span->heap->finalize);
02454 #endif
02455     if (defer) {
02456         _rpmalloc_deallocate_defer_free_span(span->heap, span);
02457         return;
02458     }
02459     rpmalloc_assert(span->heap->full_span_count, "Heap span counter corrupted");
02460     --span->heap->full_span_count;
02461 #if RPMALLOC_FIRST_CLASS_HEAPS
02462     _rpmalloc_span_double_link_list_remove(&span->heap->large_huge_span, span);
02463 #endif
02464 #if ENABLE_ADAPTIVE_THREAD_CACHE || ENABLE_STATISTICS
02465     //Decrease counter
02466     size_t idx = span->span_count - 1;
02467     atomic_decr32(&span->heap->span_use[idx].current);
02468 #endif
02469     heap_t* heap = span->heap;
02470     rpmalloc_assert(heap, "No thread heap");
02471 #if ENABLE_THREAD_CACHE
02472     const int set_as_reserved = ((span->span_count > 1) && (heap->span_cache.count == 0) && !heap->finalize && !heap->spans_reserved);
02473 #else
02474     const int set_as_reserved = ((span->span_count > 1) && !heap->finalize && !heap->spans_reserved);
02475 #endif
02476     if (set_as_reserved) {
02477         heap->span_reserve = span;
02478         heap->spans_reserved = span->span_count;
02479         if (span->flags & SPAN_FLAG_MASTER) {
02480             heap->span_reserve_master = span;
02481         } else { //SPAN_FLAG_SUBSPAN
02482             span_t* master = (span_t*)pointer_offset(span, -(intptr_t)((size_t)span->offset_from_master * _memory_span_size));
02483             heap->span_reserve_master = master;
02484             rpmalloc_assert(master->flags & SPAN_FLAG_MASTER, "Span flag corrupted");
02485             rpmalloc_assert(atomic_load32(&master->remaining_spans) >= (int32_t)span->span_count, "Master span count corrupted");
02486         }
02487         _rpmalloc_stat_inc(&heap->span_use[idx].spans_to_reserved);
02488     } else {
02489         //Insert into cache list
02490         _rpmalloc_heap_cache_insert(heap, span);
02491     }
02492 }
02493 
02495 static void
02496 _rpmalloc_deallocate_huge(span_t* span) {
02497     rpmalloc_assert(span->heap, "No span heap");
02498 #if RPMALLOC_FIRST_CLASS_HEAPS
02499     int defer = (span->heap->owner_thread && (span->heap->owner_thread != get_thread_id()) && !span->heap->finalize);
02500 #else
02501     int defer = ((span->heap->owner_thread != get_thread_id()) && !span->heap->finalize);
02502 #endif
02503     if (defer) {
02504         _rpmalloc_deallocate_defer_free_span(span->heap, span);
02505         return;
02506     }
02507     rpmalloc_assert(span->heap->full_span_count, "Heap span counter corrupted");
02508     --span->heap->full_span_count;
02509 #if RPMALLOC_FIRST_CLASS_HEAPS
02510     _rpmalloc_span_double_link_list_remove(&span->heap->large_huge_span, span);
02511 #endif
02512 
02513     //Oversized allocation, page count is stored in span_count
02514     size_t num_pages = span->span_count;
02515     _rpmalloc_unmap(span, num_pages * _memory_page_size, span->align_offset, num_pages * _memory_page_size);
02516     _rpmalloc_stat_sub(&_huge_pages_current, num_pages);
02517 }
02518 
02520 static void
02521 _rpmalloc_deallocate(void* p) {
02522     _rpmalloc_stat_add64(&_deallocation_counter, 1);
02523     //Grab the span (always at start of span, using span alignment)
02524     span_t* span = (span_t*)((uintptr_t)p & _memory_span_mask);
02525     if (UNEXPECTED(!span))
02526         return;
02527     if (EXPECTED(span->size_class < SIZE_CLASS_COUNT))
02528         _rpmalloc_deallocate_small_or_medium(span, p);
02529     else if (span->size_class == SIZE_CLASS_LARGE)
02530         _rpmalloc_deallocate_large(span);
02531     else
02532         _rpmalloc_deallocate_huge(span);
02533 }
02534 
02540 
02541 static size_t
02542 _rpmalloc_usable_size(void* p);
02543 
02545 static void*
02546 _rpmalloc_reallocate(heap_t* heap, void* p, size_t size, size_t oldsize, unsigned int flags) {
02547     if (p) {
02548         //Grab the span using guaranteed span alignment
02549         span_t* span = (span_t*)((uintptr_t)p & _memory_span_mask);
02550         if (EXPECTED(span->size_class < SIZE_CLASS_COUNT)) {
02551             //Small/medium sized block
02552             rpmalloc_assert(span->span_count == 1, "Span counter corrupted");
02553             void* blocks_start = pointer_offset(span, SPAN_HEADER_SIZE);
02554             uint32_t block_offset = (uint32_t)pointer_diff(p, blocks_start);
02555             uint32_t block_idx = block_offset / span->block_size;
02556             void* block = pointer_offset(blocks_start, (size_t)block_idx * span->block_size);
02557             if (!oldsize)
02558                 oldsize = (size_t)((ptrdiff_t)span->block_size - pointer_diff(p, block));
02559             if ((size_t)span->block_size >= size) {
02560                 //Still fits in block, never mind trying to save memory, but preserve data if alignment changed
02561                 if ((p != block) && !(flags & RPMALLOC_NO_PRESERVE))
02562                     memmove(block, p, oldsize);
02563                 return block;
02564             }
02565         } else if (span->size_class == SIZE_CLASS_LARGE) {
02566             //Large block
02567             size_t total_size = size + SPAN_HEADER_SIZE;
02568             size_t num_spans = total_size >> _memory_span_size_shift;
02569             if (total_size & (_memory_span_mask - 1))
02570                 ++num_spans;
02571             size_t current_spans = span->span_count;
02572             void* block = pointer_offset(span, SPAN_HEADER_SIZE);
02573             if (!oldsize)
02574                 oldsize = (current_spans * _memory_span_size) - (size_t)pointer_diff(p, block) - SPAN_HEADER_SIZE;
02575             if ((current_spans >= num_spans) && (total_size >= (oldsize / 2))) {
02576                 //Still fits in block, never mind trying to save memory, but preserve data if alignment changed
02577                 if ((p != block) && !(flags & RPMALLOC_NO_PRESERVE))
02578                     memmove(block, p, oldsize);
02579                 return block;
02580             }
02581         } else {
02582             //Oversized block
02583             size_t total_size = size + SPAN_HEADER_SIZE;
02584             size_t num_pages = total_size >> _memory_page_size_shift;
02585             if (total_size & (_memory_page_size - 1))
02586                 ++num_pages;
02587             //Page count is stored in span_count
02588             size_t current_pages = span->span_count;
02589             void* block = pointer_offset(span, SPAN_HEADER_SIZE);
02590             if (!oldsize)
02591                 oldsize = (current_pages * _memory_page_size) - (size_t)pointer_diff(p, block) - SPAN_HEADER_SIZE;
02592             if ((current_pages >= num_pages) && (num_pages >= (current_pages / 2))) {
02593                 //Still fits in block, never mind trying to save memory, but preserve data if alignment changed
02594                 if ((p != block) && !(flags & RPMALLOC_NO_PRESERVE))
02595                     memmove(block, p, oldsize);
02596                 return block;
02597             }
02598         }
02599     } else {
02600         oldsize = 0;
02601     }
02602 
02603     if (!!(flags & RPMALLOC_GROW_OR_FAIL))
02604         return 0;
02605 
02606     //Size is greater than block size, need to allocate a new block and deallocate the old
02607     //Avoid hysteresis by overallocating if increase is small (below 37%)
02608     size_t lower_bound = oldsize + (oldsize >> 2) + (oldsize >> 3);
02609     size_t new_size = (size > lower_bound) ? size : ((size > oldsize) ? lower_bound : size);
02610     void* block = _rpmalloc_allocate(heap, new_size);
02611     if (p && block) {
02612         if (!(flags & RPMALLOC_NO_PRESERVE))
02613             memcpy(block, p, oldsize < new_size ? oldsize : new_size);
02614         _rpmalloc_deallocate(p);
02615     }
02616 
02617     return block;
02618 }
02619 
02620 static void*
02621 _rpmalloc_aligned_reallocate(heap_t* heap, void* ptr, size_t alignment, size_t size, size_t oldsize,
02622                            unsigned int flags) {
02623     if (alignment <= SMALL_GRANULARITY)
02624         return _rpmalloc_reallocate(heap, ptr, size, oldsize, flags);
02625 
02626     int no_alloc = !!(flags & RPMALLOC_GROW_OR_FAIL);
02627     size_t usablesize = (ptr ? _rpmalloc_usable_size(ptr) : 0);
02628     if ((usablesize >= size) && !((uintptr_t)ptr & (alignment - 1))) {
02629         if (no_alloc || (size >= (usablesize / 2)))
02630             return ptr;
02631     }
02632     // Aligned alloc marks span as having aligned blocks
02633     void* block = (!no_alloc ? _rpmalloc_aligned_allocate(heap, alignment, size) : 0);
02634     if (EXPECTED(block != 0)) {
02635         if (!(flags & RPMALLOC_NO_PRESERVE) && ptr) {
02636             if (!oldsize)
02637                 oldsize = usablesize;
02638             memcpy(block, ptr, oldsize < size ? oldsize : size);
02639         }
02640         _rpmalloc_deallocate(ptr);
02641     }
02642     return block;
02643 }
02644 
02645 
02651 
02653 static size_t
02654 _rpmalloc_usable_size(void* p) {
02655     //Grab the span using guaranteed span alignment
02656     span_t* span = (span_t*)((uintptr_t)p & _memory_span_mask);
02657     if (span->size_class < SIZE_CLASS_COUNT) {
02658         //Small/medium block
02659         void* blocks_start = pointer_offset(span, SPAN_HEADER_SIZE);
02660         return span->block_size - ((size_t)pointer_diff(p, blocks_start) % span->block_size);
02661     }
02662     if (span->size_class == SIZE_CLASS_LARGE) {
02663         //Large block
02664         size_t current_spans = span->span_count;
02665         return (current_spans * _memory_span_size) - (size_t)pointer_diff(p, span);
02666     }
02667     //Oversized block, page count is stored in span_count
02668     size_t current_pages = span->span_count;
02669     return (current_pages * _memory_page_size) - (size_t)pointer_diff(p, span);
02670 }
02671 
02673 static void
02674 _rpmalloc_adjust_size_class(size_t iclass) {
02675     size_t block_size = _memory_size_class[iclass].block_size;
02676     size_t block_count = (_memory_span_size - SPAN_HEADER_SIZE) / block_size;
02677 
02678     _memory_size_class[iclass].block_count = (uint16_t)block_count;
02679     _memory_size_class[iclass].class_idx = (uint16_t)iclass;
02680 
02681     //Check if previous size classes can be merged
02682     if (iclass >= SMALL_CLASS_COUNT) {
02683         size_t prevclass = iclass;
02684         while (prevclass > 0) {
02685             --prevclass;
02686             //A class can be merged if number of pages and number of blocks are equal
02687             if (_memory_size_class[prevclass].block_count == _memory_size_class[iclass].block_count)
02688                 memcpy(_memory_size_class + prevclass, _memory_size_class + iclass, sizeof(_memory_size_class[iclass]));
02689             else
02690                 break;
02691         }
02692     }
02693 }
