02696 TRACY_API int
02697 rpmalloc_initialize(void) {
02698     if (_rpmalloc_initialized) {
02699         rpmalloc_thread_initialize();
02700         return 0;
02701     }
02702     return rpmalloc_initialize_config(0);
02703 }
02704 
02705 int
02706 rpmalloc_initialize_config(const rpmalloc_config_t* config) {
02707     if (_rpmalloc_initialized) {
02708         rpmalloc_thread_initialize();
02709         return 0;
02710     }
02711     _rpmalloc_initialized = 1;
02712 
02713     if (config)
02714         memcpy(&_memory_config, config, sizeof(rpmalloc_config_t));
02715     else
02716         memset(&_memory_config, 0, sizeof(rpmalloc_config_t));
02717 
02718     if (!_memory_config.memory_map || !_memory_config.memory_unmap) {
02719         _memory_config.memory_map = _rpmalloc_mmap_os;
02720         _memory_config.memory_unmap = _rpmalloc_unmap_os;
02721     }
02722 
02723 #if PLATFORM_WINDOWS
02724     SYSTEM_INFO system_info;
02725     memset(&system_info, 0, sizeof(system_info));
02726     GetSystemInfo(&system_info);
02727     _memory_map_granularity = system_info.dwAllocationGranularity;
02728 #else
02729     _memory_map_granularity = (size_t)sysconf(_SC_PAGESIZE);
02730 #endif
02731 
02732 #if RPMALLOC_CONFIGURABLE
02733     _memory_page_size = _memory_config.page_size;
02734 #else
02735     _memory_page_size = 0;
02736 #endif
02737     _memory_huge_pages = 0;
02738     if (!_memory_page_size) {
02739 #if PLATFORM_WINDOWS
02740         _memory_page_size = system_info.dwPageSize;
02741 #else
02742         _memory_page_size = _memory_map_granularity;
02743         if (_memory_config.enable_huge_pages) {
02744 #if defined(__linux__)
02745             size_t huge_page_size = 0;
02746             FILE* meminfo = fopen("/proc/meminfo", "r");
02747             if (meminfo) {
02748                 char line[128];
02749                 while (!huge_page_size && fgets(line, sizeof(line) - 1, meminfo)) {
02750                     line[sizeof(line) - 1] = 0;
02751                     if (strstr(line, "Hugepagesize:"))
02752                         huge_page_size = (size_t)strtol(line + 13, 0, 10) * 1024;
02753                 }
02754                 fclose(meminfo);
02755             }
02756             if (huge_page_size) {
02757                 _memory_huge_pages = 1;
02758                 _memory_page_size = huge_page_size;
02759                 _memory_map_granularity = huge_page_size;
02760             }
02761 #elif defined(__FreeBSD__)
02762             int rc;
02763             size_t sz = sizeof(rc);
02764 
02765             if (sysctlbyname("vm.pmap.pg_ps_enabled", &rc, &sz, NULL, 0) == 0 && rc == 1) {
02766                 _memory_huge_pages = 1;
02767                 _memory_page_size = 2 * 1024 * 1024;
02768                 _memory_map_granularity = _memory_page_size;
02769             }
02770 #elif defined(__APPLE__) || defined(__NetBSD__)
02771             _memory_huge_pages = 1;
02772             _memory_page_size = 2 * 1024 * 1024;
02773             _memory_map_granularity = _memory_page_size;
02774 #endif
02775         }
02776 #endif
02777     } else {
02778         if (_memory_config.enable_huge_pages)
02779             _memory_huge_pages = 1;
02780     }
02781 
02782 #if PLATFORM_WINDOWS
02783     if (_memory_config.enable_huge_pages) {
02784         HANDLE token = 0;
02785         size_t large_page_minimum = GetLargePageMinimum();
02786         if (large_page_minimum)
02787             OpenProcessToken(GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &token);
02788         if (token) {
02789             LUID luid;
02790             if (LookupPrivilegeValue(0, SE_LOCK_MEMORY_NAME, &luid)) {
02791                 TOKEN_PRIVILEGES token_privileges;
02792                 memset(&token_privileges, 0, sizeof(token_privileges));
02793                 token_privileges.PrivilegeCount = 1;
02794                 token_privileges.Privileges[0].Luid = luid;
02795                 token_privileges.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;
02796                 if (AdjustTokenPrivileges(token, FALSE, &token_privileges, 0, 0, 0)) {
02797                     if (GetLastError() == ERROR_SUCCESS)
02798                         _memory_huge_pages = 1;
02799                 }
02800             }
02801             CloseHandle(token);
02802         }
02803         if (_memory_huge_pages) {
02804             if (large_page_minimum > _memory_page_size)
02805                 _memory_page_size = large_page_minimum;
02806             if (large_page_minimum > _memory_map_granularity)
02807                 _memory_map_granularity = large_page_minimum;
02808         }
02809     }
02810 #endif
02811 
02812     size_t min_span_size = 256;
02813     size_t max_page_size;
02814 #if UINTPTR_MAX > 0xFFFFFFFF
02815     max_page_size = 4096ULL * 1024ULL * 1024ULL;
02816 #else
02817     max_page_size = 4 * 1024 * 1024;
02818 #endif
02819     if (_memory_page_size < min_span_size)
02820         _memory_page_size = min_span_size;
02821     if (_memory_page_size > max_page_size)
02822         _memory_page_size = max_page_size;
02823     _memory_page_size_shift = 0;
02824     size_t page_size_bit = _memory_page_size;
02825     while (page_size_bit != 1) {
02826         ++_memory_page_size_shift;
02827         page_size_bit >>= 1;
02828     }
02829     _memory_page_size = ((size_t)1 << _memory_page_size_shift);
02830 
02831 #if RPMALLOC_CONFIGURABLE
02832     if (!_memory_config.span_size) {
02833         _memory_span_size = _memory_default_span_size;
02834         _memory_span_size_shift = _memory_default_span_size_shift;
02835         _memory_span_mask = _memory_default_span_mask;
02836     } else {
02837         size_t span_size = _memory_config.span_size;
02838         if (span_size > (256 * 1024))
02839             span_size = (256 * 1024);
02840         _memory_span_size = 4096;
02841         _memory_span_size_shift = 12;
02842         while (_memory_span_size < span_size) {
02843             _memory_span_size <<= 1;
02844             ++_memory_span_size_shift;
02845         }
02846         _memory_span_mask = ~(uintptr_t)(_memory_span_size - 1);
02847     }
02848 #endif
02849 
02850     _memory_span_map_count = ( _memory_config.span_map_count ? _memory_config.span_map_count : DEFAULT_SPAN_MAP_COUNT);
02851     if ((_memory_span_size * _memory_span_map_count) < _memory_page_size)
02852         _memory_span_map_count = (_memory_page_size / _memory_span_size);
02853     if ((_memory_page_size >= _memory_span_size) && ((_memory_span_map_count * _memory_span_size) % _memory_page_size))
02854         _memory_span_map_count = (_memory_page_size / _memory_span_size);
02855     _memory_heap_reserve_count = (_memory_span_map_count > DEFAULT_SPAN_MAP_COUNT) ? DEFAULT_SPAN_MAP_COUNT : _memory_span_map_count;
02856 
02857     _memory_config.page_size = _memory_page_size;
02858     _memory_config.span_size = _memory_span_size;
02859     _memory_config.span_map_count = _memory_span_map_count;
02860     _memory_config.enable_huge_pages = _memory_huge_pages;
02861 
02862 #if ((defined(__APPLE__) || defined(__HAIKU__)) && ENABLE_PRELOAD) || defined(__TINYC__)
02863     if (pthread_key_create(&_memory_thread_heap, _rpmalloc_heap_release_raw_fc))
02864         return -1;
02865 #endif
02866 #if defined(_WIN32) && (!defined(BUILD_DYNAMIC_LINK) || !BUILD_DYNAMIC_LINK)
02867     fls_key = FlsAlloc(&_rpmalloc_thread_destructor);
02868 #endif
02869 
02870     //Setup all small and medium size classes
02871     size_t iclass = 0;
02872     _memory_size_class[iclass].block_size = SMALL_GRANULARITY;
02873     _rpmalloc_adjust_size_class(iclass);
02874     for (iclass = 1; iclass < SMALL_CLASS_COUNT; ++iclass) {
02875         size_t size = iclass * SMALL_GRANULARITY;
02876         _memory_size_class[iclass].block_size = (uint32_t)size;
02877         _rpmalloc_adjust_size_class(iclass);
02878     }
02879     //At least two blocks per span, then fall back to large allocations
02880     _memory_medium_size_limit = (_memory_span_size - SPAN_HEADER_SIZE) >> 1;
02881     if (_memory_medium_size_limit > MEDIUM_SIZE_LIMIT)
02882         _memory_medium_size_limit = MEDIUM_SIZE_LIMIT;
02883     for (iclass = 0; iclass < MEDIUM_CLASS_COUNT; ++iclass) {
02884         size_t size = SMALL_SIZE_LIMIT + ((iclass + 1) * MEDIUM_GRANULARITY);
02885         if (size > _memory_medium_size_limit)
02886             break;
02887         _memory_size_class[SMALL_CLASS_COUNT + iclass].block_size = (uint32_t)size;
02888         _rpmalloc_adjust_size_class(SMALL_CLASS_COUNT + iclass);
02889     }
02890 
02891     _memory_orphan_heaps = 0;
02892 #if RPMALLOC_FIRST_CLASS_HEAPS
02893     _memory_first_class_orphan_heaps = 0;
02894 #endif
02895 #if ENABLE_STATISTICS
02896     atomic_store32(&_memory_active_heaps, 0);
02897     atomic_store32(&_mapped_pages, 0);
02898     _mapped_pages_peak = 0;
02899     atomic_store32(&_master_spans, 0);
02900     atomic_store32(&_mapped_total, 0);
02901     atomic_store32(&_unmapped_total, 0);
02902     atomic_store32(&_mapped_pages_os, 0);
02903     atomic_store32(&_huge_pages_current, 0);
02904     _huge_pages_peak = 0;
02905 #endif
02906     memset(_memory_heaps, 0, sizeof(_memory_heaps));
02907     atomic_store32_release(&_memory_global_lock, 0);
02908 
02909     //Initialize this thread
02910     rpmalloc_thread_initialize();
02911     return 0;
02912 }
02913 
02915 TRACY_API void
02916 rpmalloc_finalize(void) {
02917     rpmalloc_thread_finalize(1);
02918     //rpmalloc_dump_statistics(stdout);
02919 
02920     if (_memory_global_reserve) {
02921         atomic_add32(&_memory_global_reserve_master->remaining_spans, -(int32_t)_memory_global_reserve_count);
02922         _memory_global_reserve_master = 0;
02923         _memory_global_reserve_count = 0;
02924         _memory_global_reserve = 0;
02925     }
02926     atomic_store32_release(&_memory_global_lock, 0);    
02927 
02928     //Free all thread caches and fully free spans
02929     for (size_t list_idx = 0; list_idx < HEAP_ARRAY_SIZE; ++list_idx) {
02930         heap_t* heap = _memory_heaps[list_idx];
02931         while (heap) {
02932             heap_t* next_heap = heap->next_heap;
02933             heap->finalize = 1;
02934             _rpmalloc_heap_global_finalize(heap);
02935             heap = next_heap;
02936         }
02937     }
02938 
02939 #if ENABLE_GLOBAL_CACHE
02940     //Free global caches
02941     for (size_t iclass = 0; iclass < LARGE_CLASS_COUNT; ++iclass)
02942         _rpmalloc_global_cache_finalize(&_memory_span_cache[iclass]);
02943 #endif
02944 
02945 #if (defined(__APPLE__) || defined(__HAIKU__)) && ENABLE_PRELOAD
02946     pthread_key_delete(_memory_thread_heap);
02947 #endif
02948 #if defined(_WIN32) && (!defined(BUILD_DYNAMIC_LINK) || !BUILD_DYNAMIC_LINK)
02949     FlsFree(fls_key);
02950     fls_key = 0;
02951 #endif
02952 #if ENABLE_STATISTICS
02953     //If you hit these asserts you probably have memory leaks (perhaps global scope data doing dynamic allocations) or double frees in your code
02954     rpmalloc_assert(atomic_load32(&_mapped_pages) == 0, "Memory leak detected");
02955     rpmalloc_assert(atomic_load32(&_mapped_pages_os) == 0, "Memory leak detected");
02956 #endif
02957 
02958     _rpmalloc_initialized = 0;
02959 }
02960 
02962 TRACY_API void
02963 rpmalloc_thread_initialize(void) {
02964     if (!get_thread_heap_raw()) {
02965         heap_t* heap = _rpmalloc_heap_allocate(0);
02966         if (heap) {
02967             _rpmalloc_stat_inc(&_memory_active_heaps);
02968             set_thread_heap(heap);
02969 #if defined(_WIN32) && (!defined(BUILD_DYNAMIC_LINK) || !BUILD_DYNAMIC_LINK)
02970             FlsSetValue(fls_key, heap);
02971 #endif
02972         }
02973     }
02974 }
02975 
02977 TRACY_API void
02978 rpmalloc_thread_finalize(int release_caches) {
02979     heap_t* heap = get_thread_heap_raw();
02980     if (heap)
02981         _rpmalloc_heap_release_raw(heap, release_caches);
02982     set_thread_heap(0);
02983 #if defined(_WIN32) && (!defined(BUILD_DYNAMIC_LINK) || !BUILD_DYNAMIC_LINK)
02984     FlsSetValue(fls_key, 0);
02985 #endif
02986 }
