03017 extern inline RPMALLOC_ALLOCATOR void*
03018 rpcalloc(size_t num, size_t size) {
03019     size_t total;
03020 #if ENABLE_VALIDATE_ARGS
03021 #if PLATFORM_WINDOWS
03022     int err = SizeTMult(num, size, &total);
03023     if ((err != S_OK) || (total >= MAX_ALLOC_SIZE)) {
03024         errno = EINVAL;
03025         return 0;
03026     }
03027 #else
03028     int err = __builtin_umull_overflow(num, size, &total);
03029     if (err || (total >= MAX_ALLOC_SIZE)) {
03030         errno = EINVAL;
03031         return 0;
03032     }
03033 #endif
03034 #else
03035     total = num * size;
03036 #endif
03037     heap_t* heap = get_thread_heap();
03038     void* block = _rpmalloc_allocate(heap, total);
03039     if (block)
03040         memset(block, 0, total);
03041     return block;
03042 }
03043 
03044 TRACY_API RPMALLOC_ALLOCATOR void*
03045 rprealloc(void* ptr, size_t size) {
03046 #if ENABLE_VALIDATE_ARGS
03047     if (size >= MAX_ALLOC_SIZE) {
03048         errno = EINVAL;
03049         return ptr;
03050     }
03051 #endif
03052     heap_t* heap = get_thread_heap();
03053     return _rpmalloc_reallocate(heap, ptr, size, 0, 0);
03054 }
