03056 extern RPMALLOC_ALLOCATOR void*
03057 rpaligned_realloc(void* ptr, size_t alignment, size_t size, size_t oldsize,
03058                   unsigned int flags) {
03059 #if ENABLE_VALIDATE_ARGS
03060     if ((size + alignment < size) || (alignment > _memory_page_size)) {
03061         errno = EINVAL;
03062         return 0;
03063     }
03064 #endif
03065     heap_t* heap = get_thread_heap();
03066     return _rpmalloc_aligned_reallocate(heap, ptr, alignment, size, oldsize, flags);
03067 }
