03075 extern inline RPMALLOC_ALLOCATOR void*
03076 rpaligned_calloc(size_t alignment, size_t num, size_t size) {
03077     size_t total;
03078 #if ENABLE_VALIDATE_ARGS
03079 #if PLATFORM_WINDOWS
03080     int err = SizeTMult(num, size, &total);
03081     if ((err != S_OK) || (total >= MAX_ALLOC_SIZE)) {
03082         errno = EINVAL;
03083         return 0;
03084     }
03085 #else
03086     int err = __builtin_umull_overflow(num, size, &total);
03087     if (err || (total >= MAX_ALLOC_SIZE)) {
03088         errno = EINVAL;
03089         return 0;
03090     }
03091 #endif
03092 #else
03093     total = num * size;
03094 #endif
03095     void* block = rpaligned_alloc(alignment, total);
03096     if (block)
03097         memset(block, 0, total);
03098     return block;
03099 }
