03124 void
03125 rpmalloc_thread_statistics(rpmalloc_thread_statistics_t* stats) {
03126     memset(stats, 0, sizeof(rpmalloc_thread_statistics_t));
03127     heap_t* heap = get_thread_heap_raw();
03128     if (!heap)
03129         return;
03130 
03131     for (size_t iclass = 0; iclass < SIZE_CLASS_COUNT; ++iclass) {
03132         size_class_t* size_class = _memory_size_class + iclass;
03133         span_t* span = heap->size_class[iclass].partial_span;
03134         while (span) {
03135             size_t free_count = span->list_size;
03136             size_t block_count = size_class->block_count;
03137             if (span->free_list_limit < block_count)
03138                 block_count = span->free_list_limit;
03139             free_count += (block_count - span->used_count);
03140             stats->sizecache = free_count * size_class->block_size;
03141             span = span->next;
03142         }
03143     }
03144 
03145 #if ENABLE_THREAD_CACHE
03146     for (size_t iclass = 0; iclass < LARGE_CLASS_COUNT; ++iclass) {
03147         span_cache_t* span_cache;
03148         if (!iclass)
03149             span_cache = &heap->span_cache;
03150         else
03151             span_cache = (span_cache_t*)(heap->span_large_cache + (iclass - 1));
03152         stats->spancache = span_cache->count * (iclass + 1) * _memory_span_size;
03153     }
03154 #endif
03155 
03156     span_t* deferred = (span_t*)atomic_load_ptr(&heap->span_free_deferred);
03157     while (deferred) {
03158         if (deferred->size_class != SIZE_CLASS_HUGE)
03159             stats->spancache = (size_t)deferred->span_count * _memory_span_size;
03160         deferred = (span_t*)deferred->free_list;
03161     }
03162 
03163 #if ENABLE_STATISTICS
03164     stats->thread_to_global = (size_t)atomic_load64(&heap->thread_to_global);
03165     stats->global_to_thread = (size_t)atomic_load64(&heap->global_to_thread);
03166 
03167     for (size_t iclass = 0; iclass < LARGE_CLASS_COUNT; ++iclass) {
03168         stats->span_use[iclass].current = (size_t)atomic_load32(&heap->span_use[iclass].current);
03169         stats->span_use[iclass].peak = (size_t)atomic_load32(&heap->span_use[iclass].high);
03170         stats->span_use[iclass].to_global = (size_t)atomic_load32(&heap->span_use[iclass].spans_to_global);
03171         stats->span_use[iclass].from_global = (size_t)atomic_load32(&heap->span_use[iclass].spans_from_global);
03172         stats->span_use[iclass].to_cache = (size_t)atomic_load32(&heap->span_use[iclass].spans_to_cache);
03173         stats->span_use[iclass].from_cache = (size_t)atomic_load32(&heap->span_use[iclass].spans_from_cache);
03174         stats->span_use[iclass].to_reserved = (size_t)atomic_load32(&heap->span_use[iclass].spans_to_reserved);
03175         stats->span_use[iclass].from_reserved = (size_t)atomic_load32(&heap->span_use[iclass].spans_from_reserved);
03176         stats->span_use[iclass].map_calls = (size_t)atomic_load32(&heap->span_use[iclass].spans_map_calls);
03177     }
03178     for (size_t iclass = 0; iclass < SIZE_CLASS_COUNT; ++iclass) {
03179         stats->size_use[iclass].alloc_current = (size_t)atomic_load32(&heap->size_class_use[iclass].alloc_current);
03180         stats->size_use[iclass].alloc_peak = (size_t)heap->size_class_use[iclass].alloc_peak;
03181         stats->size_use[iclass].alloc_total = (size_t)atomic_load32(&heap->size_class_use[iclass].alloc_total);
03182         stats->size_use[iclass].free_total = (size_t)atomic_load32(&heap->size_class_use[iclass].free_total);
03183         stats->size_use[iclass].spans_to_cache = (size_t)atomic_load32(&heap->size_class_use[iclass].spans_to_cache);
03184         stats->size_use[iclass].spans_from_cache = (size_t)atomic_load32(&heap->size_class_use[iclass].spans_from_cache);
03185         stats->size_use[iclass].spans_from_reserved = (size_t)atomic_load32(&heap->size_class_use[iclass].spans_from_reserved);
03186         stats->size_use[iclass].map_calls = (size_t)atomic_load32(&heap->size_class_use[iclass].spans_map_calls);
03187     }
03188 #endif
03189 }
03190 
03191 void
03192 rpmalloc_global_statistics(rpmalloc_global_statistics_t* stats) {
03193     memset(stats, 0, sizeof(rpmalloc_global_statistics_t));
03194 #if ENABLE_STATISTICS
03195     stats->mapped = (size_t)atomic_load32(&_mapped_pages) * _memory_page_size;
03196     stats->mapped_peak = (size_t)_mapped_pages_peak * _memory_page_size;
03197     stats->mapped_total = (size_t)atomic_load32(&_mapped_total) * _memory_page_size;
03198     stats->unmapped_total = (size_t)atomic_load32(&_unmapped_total) * _memory_page_size;
03199     stats->huge_alloc = (size_t)atomic_load32(&_huge_pages_current) * _memory_page_size;
03200     stats->huge_alloc_peak = (size_t)_huge_pages_peak * _memory_page_size;
03201 #endif
03202 #if ENABLE_GLOBAL_CACHE
03203     for (size_t iclass = 0; iclass < LARGE_CLASS_COUNT; ++iclass)
03204         stats->cached += _memory_span_cache[iclass].count * (iclass + 1) * _memory_span_size;
03205 #endif
03206 }
