03210 static void
03211 _memory_heap_dump_statistics(heap_t* heap, void* file) {
03212     fprintf(file, "Heap %d stats:\n", heap->id);
03213     fprintf(file, "Class   CurAlloc  PeakAlloc   TotAlloc    TotFree  BlkSize BlkCount SpansCur SpansPeak  PeakAllocMiB  ToCacheMiB FromCacheMiB FromReserveMiB MmapCalls\n");
03214     for (size_t iclass = 0; iclass < SIZE_CLASS_COUNT; ++iclass) {
03215         if (!atomic_load32(&heap->size_class_use[iclass].alloc_total))
03216             continue;
03217         fprintf(file, "%3u:  %10u %10u %10u %10u %8u %8u %8d %9d %13zu %11zu %12zu %14zu %9u\n", (uint32_t)iclass,
03218             atomic_load32(&heap->size_class_use[iclass].alloc_current),
03219             heap->size_class_use[iclass].alloc_peak,
03220             atomic_load32(&heap->size_class_use[iclass].alloc_total),
03221             atomic_load32(&heap->size_class_use[iclass].free_total),
03222             _memory_size_class[iclass].block_size,
03223             _memory_size_class[iclass].block_count,
03224             atomic_load32(&heap->size_class_use[iclass].spans_current),
03225             heap->size_class_use[iclass].spans_peak,
03226             ((size_t)heap->size_class_use[iclass].alloc_peak * (size_t)_memory_size_class[iclass].block_size) / (size_t)(1024 * 1024),
03227             ((size_t)atomic_load32(&heap->size_class_use[iclass].spans_to_cache) * _memory_span_size) / (size_t)(1024 * 1024),
03228             ((size_t)atomic_load32(&heap->size_class_use[iclass].spans_from_cache) * _memory_span_size) / (size_t)(1024 * 1024),
03229             ((size_t)atomic_load32(&heap->size_class_use[iclass].spans_from_reserved) * _memory_span_size) / (size_t)(1024 * 1024),
03230             atomic_load32(&heap->size_class_use[iclass].spans_map_calls));
03231     }
03232     fprintf(file, "Spans  Current     Peak Deferred  PeakMiB  Cached  ToCacheMiB FromCacheMiB ToReserveMiB FromReserveMiB ToGlobalMiB FromGlobalMiB  MmapCalls\n");
03233     for (size_t iclass = 0; iclass < LARGE_CLASS_COUNT; ++iclass) {
03234         if (!atomic_load32(&heap->span_use[iclass].high) && !atomic_load32(&heap->span_use[iclass].spans_map_calls))
03235             continue;
03236         fprintf(file, "%4u: %8d %8u %8u %8zu %7u %11zu %12zu %12zu %14zu %11zu %13zu %10u\n", (uint32_t)(iclass + 1),
03237             atomic_load32(&heap->span_use[iclass].current),
03238             atomic_load32(&heap->span_use[iclass].high),
03239             atomic_load32(&heap->span_use[iclass].spans_deferred),
03240             ((size_t)atomic_load32(&heap->span_use[iclass].high) * (size_t)_memory_span_size * (iclass + 1)) / (size_t)(1024 * 1024),
03241 #if ENABLE_THREAD_CACHE
03242             (unsigned int)(!iclass ? heap->span_cache.count : heap->span_large_cache[iclass - 1].count),
03243             ((size_t)atomic_load32(&heap->span_use[iclass].spans_to_cache) * (iclass + 1) * _memory_span_size) / (size_t)(1024 * 1024),
03244             ((size_t)atomic_load32(&heap->span_use[iclass].spans_from_cache) * (iclass + 1) * _memory_span_size) / (size_t)(1024 * 1024),
03245 #else
03246             0, (size_t)0, (size_t)0,
03247 #endif
03248             ((size_t)atomic_load32(&heap->span_use[iclass].spans_to_reserved) * (iclass + 1) * _memory_span_size) / (size_t)(1024 * 1024),
03249             ((size_t)atomic_load32(&heap->span_use[iclass].spans_from_reserved) * (iclass + 1) * _memory_span_size) / (size_t)(1024 * 1024),
03250             ((size_t)atomic_load32(&heap->span_use[iclass].spans_to_global) * (size_t)_memory_span_size * (iclass + 1)) / (size_t)(1024 * 1024),
03251             ((size_t)atomic_load32(&heap->span_use[iclass].spans_from_global) * (size_t)_memory_span_size * (iclass + 1)) / (size_t)(1024 * 1024),
03252             atomic_load32(&heap->span_use[iclass].spans_map_calls));
03253     }
03254     fprintf(file, "Full spans: %zu\n", heap->full_span_count);
03255     fprintf(file, "ThreadToGlobalMiB GlobalToThreadMiB\n");
03256     fprintf(file, "%17zu %17zu\n", (size_t)atomic_load64(&heap->thread_to_global) / (size_t)(1024 * 1024), (size_t)atomic_load64(&heap->global_to_thread) / (size_t)(1024 * 1024));
03257 }
03258 
03259 #endif
03260 
03261 void
03262 rpmalloc_dump_statistics(void* file) {
03263 #if ENABLE_STATISTICS
03264     for (size_t list_idx = 0; list_idx < HEAP_ARRAY_SIZE; ++list_idx) {
03265         heap_t* heap = _memory_heaps[list_idx];
03266         while (heap) {
03267             int need_dump = 0;
03268             for (size_t iclass = 0; !need_dump && (iclass < SIZE_CLASS_COUNT); ++iclass) {
03269                 if (!atomic_load32(&heap->size_class_use[iclass].alloc_total)) {
03270                     rpmalloc_assert(!atomic_load32(&heap->size_class_use[iclass].free_total), "Heap statistics counter mismatch");
03271                     rpmalloc_assert(!atomic_load32(&heap->size_class_use[iclass].spans_map_calls), "Heap statistics counter mismatch");
03272                     continue;
03273                 }
03274                 need_dump = 1;
03275             }
03276             for (size_t iclass = 0; !need_dump && (iclass < LARGE_CLASS_COUNT); ++iclass) {
03277                 if (!atomic_load32(&heap->span_use[iclass].high) && !atomic_load32(&heap->span_use[iclass].spans_map_calls))
03278                     continue;
03279                 need_dump = 1;
03280             }
03281             if (need_dump)
03282                 _memory_heap_dump_statistics(heap, file);
03283             heap = heap->next_heap;
03284         }
03285     }
03286     fprintf(file, "Global stats:\n");
03287     size_t huge_current = (size_t)atomic_load32(&_huge_pages_current) * _memory_page_size;
03288     size_t huge_peak = (size_t)_huge_pages_peak * _memory_page_size;
03289     fprintf(file, "HugeCurrentMiB HugePeakMiB\n");
03290     fprintf(file, "%14zu %11zu\n", huge_current / (size_t)(1024 * 1024), huge_peak / (size_t)(1024 * 1024));
03291 
03292     fprintf(file, "GlobalCacheMiB\n");
03293     for (size_t iclass = 0; iclass < LARGE_CLASS_COUNT; ++iclass) {
03294         global_cache_t* cache = _memory_span_cache + iclass;
03295         size_t global_cache = (size_t)cache->count * iclass * _memory_span_size;
03296 
03297         size_t global_overflow_cache = 0;
03298         span_t* span = cache->overflow;
03299         while (span) {
03300             global_overflow_cache += iclass * _memory_span_size;
03301             span = span->next;
03302         }
03303         if (global_cache || global_overflow_cache || cache->insert_count || cache->extract_count)
03304             fprintf(file, "%4zu: %8zuMiB (%8zuMiB overflow) %14zu insert %14zu extract\n", iclass + 1, global_cache / (size_t)(1024 * 1024), global_overflow_cache / (size_t)(1024 * 1024), cache->insert_count, cache->extract_count);
03305     }
03306 
03307     size_t mapped = (size_t)atomic_load32(&_mapped_pages) * _memory_page_size;
03308     size_t mapped_os = (size_t)atomic_load32(&_mapped_pages_os) * _memory_page_size;
03309     size_t mapped_peak = (size_t)_mapped_pages_peak * _memory_page_size;
03310     size_t mapped_total = (size_t)atomic_load32(&_mapped_total) * _memory_page_size;
03311     size_t unmapped_total = (size_t)atomic_load32(&_unmapped_total) * _memory_page_size;
03312     fprintf(file, "MappedMiB MappedOSMiB MappedPeakMiB MappedTotalMiB UnmappedTotalMiB\n");
03313     fprintf(file, "%9zu %11zu %13zu %14zu %16zu\n",
03314         mapped / (size_t)(1024 * 1024),
03315         mapped_os / (size_t)(1024 * 1024),
03316         mapped_peak / (size_t)(1024 * 1024),
03317         mapped_total / (size_t)(1024 * 1024),
03318         unmapped_total / (size_t)(1024 * 1024));
03319 
03320     fprintf(file, "\n");
03321 #if 0
03322     int64_t allocated = atomic_load64(&_allocation_counter);
03323     int64_t deallocated = atomic_load64(&_deallocation_counter);
03324     fprintf(file, "Allocation count: %lli\n", allocated);
03325     fprintf(file, "Deallocation count: %lli\n", deallocated);
03326     fprintf(file, "Current allocations: %lli\n", (allocated - deallocated));
03327     fprintf(file, "Master spans: %d\n", atomic_load32(&_master_spans));
03328     fprintf(file, "Dangling master spans: %d\n", atomic_load32(&_unmapped_master_spans));
03329 #endif
03330 #endif
03331     (void)sizeof(file);
03332 }
