03336 extern inline rpmalloc_heap_t*
03337 rpmalloc_heap_acquire(void) {
03338     // Must be a pristine heap from newly mapped memory pages, or else memory blocks
03339     // could already be allocated from the heap which would (wrongly) be released when
03340     // heap is cleared with rpmalloc_heap_free_all(). Also heaps guaranteed to be
03341     // pristine from the dedicated orphan list can be used.
03342     heap_t* heap = _rpmalloc_heap_allocate(1);
03343     heap->owner_thread = 0;
03344     _rpmalloc_stat_inc(&_memory_active_heaps);
03345     return heap;
03346 }
03347 
03348 extern inline void
03349 rpmalloc_heap_release(rpmalloc_heap_t* heap) {
03350     if (heap)
03351         _rpmalloc_heap_release(heap, 1, 1);
03352 }
