03354 extern inline RPMALLOC_ALLOCATOR void*
03355 rpmalloc_heap_alloc(rpmalloc_heap_t* heap, size_t size) {
03356 #if ENABLE_VALIDATE_ARGS
03357     if (size >= MAX_ALLOC_SIZE) {
03358         errno = EINVAL;
