03365 extern inline RPMALLOC_ALLOCATOR void*
03366 rpmalloc_heap_aligned_alloc(rpmalloc_heap_t* heap, size_t alignment, size_t size) {
03367 #if ENABLE_VALIDATE_ARGS
03368     if (size >= MAX_ALLOC_SIZE) {
03369         errno = EINVAL;
