03376 extern inline RPMALLOC_ALLOCATOR void*
03377 rpmalloc_heap_calloc(rpmalloc_heap_t* heap, size_t num, size_t size) {
03378     return rpmalloc_heap_aligned_calloc(heap, 0, num, size);
03379 }
03380 
03381 extern inline RPMALLOC_ALLOCATOR void*
03382 rpmalloc_heap_aligned_calloc(rpmalloc_heap_t* heap, size_t alignment, size_t num, size_t size) {
03383     size_t total;
03384 #if ENABLE_VALIDATE_ARGS
03385 #if PLATFORM_WINDOWS
03386     int err = SizeTMult(num, size, &total);
03387     if ((err != S_OK) || (total >= MAX_ALLOC_SIZE)) {
03388         errno = EINVAL;
03389         return 0;
03390     }
03391 #else
03392     int err = __builtin_umull_overflow(num, size, &total);
03393     if (err || (total >= MAX_ALLOC_SIZE)) {
03394         errno = EINVAL;
03395         return 0;
03396     }
03397 #endif
03398 #else
03399     total = num * size;
03400 #endif
03401     void* block = _rpmalloc_aligned_allocate(heap, alignment, total);
03402     if (block)
03403         memset(block, 0, total);
03404     return block;
03405 }
