03407 extern inline RPMALLOC_ALLOCATOR void*
03408 rpmalloc_heap_realloc(rpmalloc_heap_t* heap, void* ptr, size_t size, unsigned int flags) {
03409 #if ENABLE_VALIDATE_ARGS
03410     if (size >= MAX_ALLOC_SIZE) {
03411         errno = EINVAL;
03412         return ptr;
03413     }
03414 #endif
03415     return _rpmalloc_reallocate(heap, ptr, size, 0, flags);
03416 }
