03418 extern inline RPMALLOC_ALLOCATOR void*
03419 rpmalloc_heap_aligned_realloc(rpmalloc_heap_t* heap, void* ptr, size_t alignment, size_t size, unsigned int flags) {
03420 #if ENABLE_VALIDATE_ARGS
03421     if ((size + alignment < size) || (alignment > _memory_page_size)) {
03422         errno = EINVAL;
03423         return 0;
03424     }
03425 #endif
03426     return _rpmalloc_aligned_reallocate(heap, ptr, alignment, size, 0, flags);  
03427 }
