03434 
03435 extern inline void
03436 rpmalloc_heap_free_all(rpmalloc_heap_t* heap) {
03437     span_t* span;
03438     span_t* next_span;
03439 
03440     _rpmalloc_heap_cache_adopt_deferred(heap, 0);
03441 
03442     for (size_t iclass = 0; iclass < SIZE_CLASS_COUNT; ++iclass) {
03443         span = heap->size_class[iclass].partial_span;
03444         while (span) {
03445             next_span = span->next;
03446             _rpmalloc_heap_cache_insert(heap, span);
03447             span = next_span;
03448         }
03449         heap->size_class[iclass].partial_span = 0;
03450         span = heap->full_span[iclass];
03451         while (span) {
03452             next_span = span->next;
03453             _rpmalloc_heap_cache_insert(heap, span);
03454             span = next_span;
03455         }
03456     }
03457     memset(heap->size_class, 0, sizeof(heap->size_class));
03458     memset(heap->full_span, 0, sizeof(heap->full_span));
03459 
03460     span = heap->large_huge_span;
03461     while (span) {
03462         next_span = span->next;
03463         if (UNEXPECTED(span->size_class == SIZE_CLASS_HUGE))
03464             _rpmalloc_deallocate_huge(span);
03465         else
03466             _rpmalloc_heap_cache_insert(heap, span);
03467         span = next_span;
03468     }
03469     heap->large_huge_span = 0;
03470     heap->full_span_count = 0;
03471 
03472 #if ENABLE_THREAD_CACHE
03473     for (size_t iclass = 0; iclass < LARGE_CLASS_COUNT; ++iclass) {
03474         span_cache_t* span_cache;
03475         if (!iclass)
03476             span_cache = &heap->span_cache;
03477         else
03478             span_cache = (span_cache_t*)(heap->span_large_cache + (iclass - 1));
03479         if (!span_cache->count)
03480             continue;
03481 #if ENABLE_GLOBAL_CACHE
03482         _rpmalloc_stat_add64(&heap->thread_to_global, span_cache->count * (iclass + 1) * _memory_span_size);
03483         _rpmalloc_stat_add(&heap->span_use[iclass].spans_to_global, span_cache->count);
03484         _rpmalloc_global_cache_insert_spans(span_cache->span, iclass + 1, span_cache->count);
03485 #else
03486         for (size_t ispan = 0; ispan < span_cache->count; ++ispan)
03487             _rpmalloc_span_unmap(span_cache->span[ispan]);
03488 #endif
03489         span_cache->count = 0;
03490     }
03491 #endif
03492 
03493 #if ENABLE_STATISTICS
03494     for (size_t iclass = 0; iclass < SIZE_CLASS_COUNT; ++iclass) {
03495         atomic_store32(&heap->size_class_use[iclass].alloc_current, 0);
03496         atomic_store32(&heap->size_class_use[iclass].spans_current, 0);
03497     }
03498     for (size_t iclass = 0; iclass < LARGE_CLASS_COUNT; ++iclass) {
03499         atomic_store32(&heap->span_use[iclass].current, 0);
03500     }
03501 #endif
03502 }
